import { Invoice, Party, Product, SpecialRate, User } from '../types';

const KEY_SCRIPT_URL = 'greemzar_script_url';
const DEFAULT_URL = 'https://script.google.com/macros/s/AKfycbzvyZRNdKDVeYmaTeHwasbi9QWYCwoskMzjrtQV_WBJ80Cj51sn6mlvdLHq5A2c7BJw_g/exec';

export const Cloud = {
  getScriptUrl: () => {
    const stored = localStorage.getItem(KEY_SCRIPT_URL);
    // Return stored if exists (and not empty string), otherwise default
    return stored || DEFAULT_URL; 
  },
  setScriptUrl: (url: string) => localStorage.setItem(KEY_SCRIPT_URL, url),

  // --- PUSH TO CLOUD (POST) ---

  syncInvoice: async (invoice: Invoice) => {
    // Send invoice directly. The Google Script handles column mapping.
    // Previously we modified product name which caused messy duplicates on read-back.
    return Cloud.postData('INVOICE', invoice);
  },

  syncProducts: async (products: Product[]) => {
    // SAFETY GUARD: Prevent syncing empty products list
    if (!products || products.length === 0) return { success: false, error: "Ignored empty product sync" };
    return Cloud.postData('PRODUCTS', products);
  },

  syncParties: async (parties: Party[]) => {
    // SAFETY GUARD: Prevent syncing empty parties list
    if (!parties || parties.length === 0) return { success: false, error: "Ignored empty party sync" };
    return Cloud.postData('PARTIES', parties);
  },

  syncUsers: async (users: User[]) => {
    return Cloud.postData('USERS', users);
  },

  syncRates: async (parties: Party[], products: Product[], rates: SpecialRate[]) => {
    // SAFETY GUARD: Cannot sync rates if master data is missing
    if (!parties.length || !products.length) return { success: false, error: "Ignored empty rates sync" };

    // Header: [ProdID, Name, StdRate, Party1Name, Party2Name...]
    const header = ['Product ID', 'Product Name', 'Standard Rate'];
    parties.forEach(p => header.push(p.name)); // Party Headers

    const rows = products.map(prod => {
      const row: (string | number)[] = [prod.id, prod.name, prod.standardRate];
      parties.forEach(party => {
        const r = rates.find(rate => rate.partyId === party.id && rate.productId === prod.id);
        row.push(r ? r.rate : '');
      });
      return row;
    });

    const matrixData = [header, ...rows];
    return Cloud.postData('RATES', matrixData);
  },

  // Helper to sync all master data in parallel
  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
     // Guards are inside individual functions
     await Promise.all([
       Cloud.syncParties(parties),
       Cloud.syncProducts(products),
       Cloud.syncRates(parties, products, rates),
       Cloud.syncUsers(users)
     ]);
  },

  // --- PULL FROM CLOUD (GET) ---

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any> => {
    const url = Cloud.getScriptUrl();
    if (!url) throw new Error('No Script URL');

    // We use a timestamp to prevent browser caching
    const fetchUrl = `${url}?type=${type}&t=${Date.now()}`;

    const response = await fetch(fetchUrl, {
      method: 'GET',
    });

    const json = await response.json();
    if (json.status === 'error') throw new Error(json.message);
    return json.data;
  },

  fetchUsers: async (): Promise<User[]> => {
    try {
      const rows = await Cloud.fetchData('USERS');
      if (!rows || rows.length < 2) return [];

      // Skip Header
      return rows.slice(1).map((r: any[]) => ({
        username: String(r[0]),
        password: String(r[1]),
        role: r[2] ? String(r[2]) : 'user'
      })).filter((u: User) => u.username);
    } catch (e) {
      console.warn("Could not fetch users, possibly sheet not setup yet.", e);
      return [];
    }
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    try {
      const rows = await Cloud.fetchData('INVOICES');
      if (!rows || rows.length < 2) return [];

      const invoiceMap = new Map<string, Invoice>();

      // Dynamic Column Mapping to support old and new script versions
      const header = rows[0].map((c: any) => String(c).toLowerCase().trim());

      // Helper to find column index with exact or partial match
      const getCol = (keywords: string[]) => {
          return header.findIndex((h: string) => keywords.some(k => h.includes(k)));
      };

      // Define possible column names for robustness
      const idxInv = getCol(['invoice #', 'invoice no']);
      const idxDate = getCol(['date']);
      const idxParty = getCol(['party', 'customer']);

      const idxAddr = getCol(['address']); 
      const idxGstIn = getCol(['gstin', 'gst number']);
      const idxAadhar = getCol(['aadhar']);
      const idxPan = getCol(['pan']);

      const idxVehicle = getCol(['vehicle']); 
      // Product Name might be "Product" or "Product Name" or "Item"
      const idxProd = getCol(['product name', 'product', 'item description']);

      const idxHsn = getCol(['hsn']);
      const idxGst = getCol(['gst %', 'tax %']);
      const idxQty = getCol(['qty', 'quantity', 'cartons']);
      const idxRate = getCol(['rate', 'price']);
      const idxItemTotal = getCol(['item total', 'amount']);

      const idxSubTotal = getCol(['subtotal']);
      const idxDiscount = getCol(['discount']);
      const idxTaxAmt = getCol(['tax amount']);

      const idxGrand = getCol(['grand total', 'total pay']);
      const idxRef = getCol(['total qty', 'po number', 'ref']);

      // FALLBACKS if headers are completely missing (e.g. old sheet structure without headers)
      // Standard: Inv(0), Date(1), Party(2) ... Qty(~6/11)

      const dataRows = rows.slice(1);

      dataRows.forEach((row: any[]) => {
        // Safe getter
        const val = (idx: number) => (idx > -1 && row[idx] !== undefined) ? row[idx] : '';
        const numVal = (idx: number) => {
           const v = val(idx);
           const n = parseFloat(String(v));
           return isNaN(n) ? 0 : n;
        };

        const invNum = String(val(idxInv > -1 ? idxInv : 0));
        if (!invNum) return;

        // --- DATE PARSING FIX ---
        // Google Sheet returns dates in many ways:
        // 1. "YYYY-MM-DD" string
        // 2. "2025-02-24T18:30:00.000Z" (Date object string)
        // 3. Date Object (if script logic passes it)
        let rawDate = String(val(idxDate > -1 ? idxDate : 1));
        let cleanDate = '';

        if (rawDate) {
             try {
                 // Try to construct a JS date object from whatever string we have
                 const d = new Date(rawDate);
                 if (!isNaN(d.getTime())) {
                     const year = d.getFullYear();
                     const month = String(d.getMonth() + 1).padStart(2, '0');
                     const day = String(d.getDate()).padStart(2, '0');
                     cleanDate = `${year}-${month}-${day}`;
                 } else {
                     // Fallback to splitting T if it fails date parsing (rare)
                     cleanDate = rawDate.split('T')[0];
                 }
             } catch(e) {
                 cleanDate = rawDate.substring(0, 10);
             }
        }
        // ------------------------

        if (!invoiceMap.has(invNum)) {
          invoiceMap.set(invNum, {
            id: invNum,
            invoiceNumber: invNum,
            date: cleanDate,
            partyName: String(val(idxParty > -1 ? idxParty : 2)),
            partyId: '', 
            // Optional fields
            partyAddress: String(val(idxAddr)),
            partyGst: String(val(idxGstIn)),
            partyAadhar: String(val(idxAadhar)),
            partyPan: String(val(idxPan)),
            items: [],
            subTotal: numVal(idxSubTotal),
            taxPercent: 0,
            taxAmount: numVal(idxTaxAmt),
            globalDiscount: numVal(idxDiscount),
            grandTotal: numVal(idxGrand > -1 ? idxGrand : 9),
            vehicleNumber: String(val(idxVehicle)),
            poNumber: String(val(idxRef)) 
          });
        }

        const inv = invoiceMap.get(invNum)!;

        // Use smart fallbacks for item details if columns not found
        // If idxProd is missing, we try to guess based on standard layout (col 8 in new, col 4 in old?)
        // Let's rely on getCol being decent. If not found, use default indices carefully.

        const qty = numVal(idxQty > -1 ? idxQty : 11); // Default to 11 (new schema)
        const rate = numVal(idxRate > -1 ? idxRate : 12); 
        const gst = numVal(idxGst);
        const baseRate = rate > 0 ? (rate / (1 + (gst/100))) : 0;

        // Clean Product Name (Remove suffix like " (5*100)" that was added by old sync logic)
        let productName = String(val(idxProd > -1 ? idxProd : 8)); // Default 8
        if (productName) {
            // Regex matches " (12*500)" or " (12.5*500.00)" at end of string
            productName = productName.replace(/\s*\(\d+(\.\d+)?\*\d+(\.\d+)?\)$/, '');
        }

        // Only add item if it looks valid
        if (productName || qty > 0 || rate > 0) {
            inv.items.push({
            id: crypto.randomUUID(),
            productId: '', 
            productName: productName || 'Unknown Item',
            hsn: String(val(idxHsn)),
            gstPercent: gst,
            quantity: qty,
            rate: rate,
            baseRate: baseRate,
            total: numVal(idxItemTotal > -1 ? idxItemTotal : 13)
            });
        }
      });

      // Convert Map to Array and Sort by Date desc (newest first)
      return Array.from(invoiceMap.values()).reverse();
    } catch (e) {
      console.error("Error parsing invoices", e);
      return [];
    }
  },

  // --- HELPERS ---

  postData: async (type: string, data: any) => {
    const url = Cloud.getScriptUrl();
    if (!url) return { success: false, error: 'No Script URL' };

    try {
      await fetch(url, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type, data })
      });
      return { success: true };
    } catch (error) {
      console.error('Cloud Error:', error);
      return { success: false, error: String(error) };
    }
  },

  testConnection: async () => {
    const url = Cloud.getScriptUrl();
    if (!url) throw new Error("URL is empty");

    const response = await fetch(`${url}?type=PING`);
    const json = await response.json();
    if (json.result !== 'success') throw new Error("Script reachable but returned error");
    return true;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';
import { exportInvoicesToCSV } from '../services/csv';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; // Added for Edit Mode
}

// Defined Vehicle Options
const VEHICLE_OPTIONS = [
  "WB894170", 
  "WB25K1322", 
  "WB25K2982", 
  "WB25L6365", 
  "WB25K1326", 
  "WB25K1341", 
  "WB47J7275", 
  "WB35H3960"
];

// Helper for Local Date (YYYY-MM-DD)
const getTodayString = () => {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);

  // Fix: Use local date function instead of toISOString() which is UTC
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());

  const [customInvoiceNo, setCustomInvoiceNo] = useState(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);

  const [refNo, setRefNo] = useState(''); // This is Total Qty

  // Global Discount State
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);

  // Cloud State
  const [isSaving, setIsSaving] = useState(false);
  const [hasCloudConfig, setHasCloudConfig] = useState(false);

  // Modal States
  const [isPartyModalOpen, setIsPartyModalOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);

  // Quick Party State
  const [newPartyName, setNewPartyName] = useState('');

  // Auto-Print Effect when Preview Opens
  useEffect(() => {
    if (isPreviewOpen && lastInvoice) {
      // Reduced delay to 50ms for near-instant print dialog
      const timer = setTimeout(() => {
        window.print();
      }, 50); 
      return () => clearTimeout(timer);
    }
  }, [isPreviewOpen, lastInvoice]);

  useEffect(() => {
    setHasCloudConfig(!!Cloud.getScriptUrl());
  }, []);

  // --- EDIT MODE INITIALIZATION ---
  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      // Sanitize items to remove NaNs and try to link IDs
      const cleanItems = initialData.items.map(item => {
        // Try to recover productId if missing (common from Cloud fetch)
        let pId = item.productId;
        if (!pId && products.length > 0) {
            // Fuzzy match name
            const found = products.find(p => p.name.trim().toLowerCase() === item.productName.trim().toLowerCase());
            if (found) pId = found.id;
        }

        return {
          ...item,
          productId: pId || '',
          quantity: isNaN(item.quantity) ? 0 : item.quantity,
          rate: isNaN(item.rate) ? 0 : item.rate,
          total: isNaN(item.total) ? 0 : item.total,
          gstPercent: isNaN(item.gstPercent || 0) ? 0 : item.gstPercent
        };
      });

      setItems(cleanItems);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setRefNo(initialData.poNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    } else {
      // Reset if no initial data (switching back to new invoice)
      setSelectedPartyId('');
      setItems([]);
      setInvoiceDate(getTodayString());
      setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
      setVehicleNo('');
      setRefNo('');
      setGlobalDiscount(0);
    }
  }, [initialData, products]); // Re-run if products load later

  // --- AUTO-CALCULATE TOTAL QTY ---
  useEffect(() => {
    const totalQty = items.reduce((sum, item) => sum + item.quantity, 0);
    if (totalQty > 0) {
      setRefNo(totalQty.toString());
    } else {
      setRefNo('');
    }
  }, [items]);

  // --- MANUAL ENTRY STATE ---

  // Vehicle State (Custom Combobox)
  const [vehicleNo, setVehicleNo] = useState('');
  const [showVehicleSuggestions, setShowVehicleSuggestions] = useState(false);
  const [vehicleHighlightIndex, setVehicleHighlightIndex] = useState(0);

  // Product State (Custom Combobox)
  const [currentProductId, setCurrentProductId] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [productHighlightIndex, setProductHighlightIndex] = useState(0);

  const [currentQty, setCurrentQty] = useState(1);
  const [currentRate, setCurrentRate] = useState(0); 
  const [overrideRate, setOverrideRate] = useState(false); 

  // Refs for Focus Management
  const invoiceNoInputRef = useRef<HTMLInputElement>(null);
  const vehicleInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);
  const addBtnRef = useRef<HTMLButtonElement>(null);

  // --- FILTERING LOGIC ---
  const filteredVehicles = VEHICLE_OPTIONS.filter(v => 
    v.toLowerCase().includes(vehicleNo.toLowerCase())
  );

  const filteredProducts = products.filter(p => {
    const terms = productSearch.toLowerCase().split(' ').filter(t => t);
    const pName = p.name.toLowerCase();
    return terms.every(term => pName.includes(term));
  });

  // --- AUTOMATED PRICING LOGIC ---
  const getRateForProduct = (prodId: string, partyId: string): number => {
    const product = products.find(p => p.id === prodId);
    if (!product) return 0;
    let rateToUse = product.standardRate;
    if (partyId) {
      const special = specialRates.find(r => r.partyId === partyId && r.productId === prodId);
      if (special) rateToUse = special.rate;
    }
    return rateToUse;
  };

  useEffect(() => {
    if (!currentProductId || overrideRate) return;
    setCurrentRate(getRateForProduct(currentProductId, selectedPartyId));
  }, [currentProductId, selectedPartyId, products, specialRates]);

  useEffect(() => {
    setOverrideRate(false);
  }, [currentProductId]);

  // --- KEYBOARD HANDLERS ---

  // 1. Global Shortcuts (Insert Key)
  useEffect(() => {
    const handleGlobalKeys = (e: KeyboardEvent) => {
      if (e.key === 'Insert') {
        e.preventDefault();
        if (isPreviewOpen) {
          handlePrint();
        } else {
          handleSaveInvoice();
        }
      }
      // Print Shortcut in Modal
      if (isPreviewOpen && (e.ctrlKey || e.metaKey) && e.key === 'p') {
        e.preventDefault();
        window.print();
      }
    };
    window.addEventListener('keydown', handleGlobalKeys);
    return () => window.removeEventListener('keydown', handleGlobalKeys);
  }, [isPreviewOpen, items, selectedPartyId]); 

  // 2. Generic Input Navigation
  const handleGenericKeyDown = (e: React.KeyboardEvent, nextRef: React.RefObject<HTMLElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      nextRef.current?.focus();
    }
  };

  // 3. Vehicle Custom Input Handler
  const handleVehicleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.min(prev + 1, filteredVehicles.length - 1));
      setShowVehicleSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showVehicleSuggestions && filteredVehicles.length > 0) {
        setVehicleNo(filteredVehicles[vehicleHighlightIndex]);
      }
      setShowVehicleSuggestions(false);
      productInputRef.current?.focus();
    } else if (e.key === 'Escape') {
      setShowVehicleSuggestions(false);
    }
  };

  // 4. Product Custom Input Handler
  const handleProductKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.min(prev + 1, filteredProducts.length - 1));
      setShowProductSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showProductSuggestions && filteredProducts.length > 0) {
        selectProduct(filteredProducts[productHighlightIndex]);
      } else {
         if (currentProductId) qtyInputRef.current?.focus();
      }
    } else if (e.key === 'Escape') {
      setShowProductSuggestions(false);
    }
  };

  // 5. Quantity Input Handler
  const handleQtyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
       e.preventDefault();
       addItem(e); 
    }
  };

  // --- SELECTION LOGIC ---

  const selectProduct = (p: Product) => {
    setProductSearch(p.name);
    setCurrentProductId(p.id);
    setShowProductSuggestions(false);
    setTimeout(() => qtyInputRef.current?.focus(), 50);
  };

  const handleProductSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setProductSearch(e.target.value);
    setCurrentProductId(''); 
    setProductHighlightIndex(0);
    setShowProductSuggestions(true);
  };

  const handleCreateParty = (e: React.FormEvent) => {
    e.preventDefault();
    if(!newPartyName.trim()) return;
    const newParty: Party = {
      id: crypto.randomUUID(),
      name: newPartyName.trim(),
      phone: '', address: '', city: '', gstNumber: '', aadharNumber: '', panNumber: ''
    };
    setParties([...parties, newParty]); 
    setSelectedPartyId(newParty.id); 
    setNewPartyName('');
    setIsPartyModalOpen(false);
  };

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    // REVERSE GST CALCULATION
    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));
    const grossTotal = currentQty * inclusiveRate; 

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,  
      total: grossTotal,   
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);

    // Reset Row
    setCurrentProductId('');
    setProductSearch('');
    setCurrentQty(1);
    setCurrentRate(0);
    setOverrideRate(false);
    setShowProductSuggestions(false);

    // Return Focus to Product Search
    productInputRef.current?.focus();
  };

  const removeItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const calculateDetails = () => {
    let subTotalInclusive = 0;
    let totalTax = 0;
    let subTotalTaxable = 0;
    let totalCGST = 0;
    let totalSGST = 0;

    items.forEach(item => {
      // Safety check for NaN
      const qty = isNaN(item.quantity) ? 0 : item.quantity;
      const rate = isNaN(item.rate) ? 0 : item.rate;
      const total = isNaN(item.total) ? 0 : item.total;
      const baseRate = isNaN(item.baseRate) ? 0 : item.baseRate;

      subTotalInclusive += total;

      const itemTaxableValue = baseRate * qty;
      const itemTaxAmount = total - itemTaxableValue;

      subTotalTaxable += itemTaxableValue;
      totalTax += itemTaxAmount;

      totalCGST += itemTaxAmount / 2;
      totalSGST += itemTaxAmount / 2;
    });

    const grandTotal = Math.max(0, subTotalInclusive - globalDiscount);
    const roundOff = Math.round(grandTotal) - grandTotal;

    return { subTotalInclusive, subTotalTaxable, totalCGST, totalSGST, grandTotal: Math.round(grandTotal), roundOff };
  };

  const { subTotalInclusive, totalCGST, totalSGST, grandTotal } = calculateDetails();

  const generateInvoiceData = (): Invoice | null => {
    if (!selectedPartyId || items.length === 0) return null;
    const party = parties.find(p => p.id === selectedPartyId);

    // STRICT TOTAL QTY CALCULATION
    const strictTotalQty = items.reduce((sum, i) => sum + i.quantity, 0);

    return {
      id: initialData ? initialData.id : crypto.randomUUID(), // Preserve ID if editing
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown',
      partyAddress: party?.address || '', // Captured Snapshot
      partyGst: party?.gstNumber || '',   // Captured Snapshot
      partyPan: party?.panNumber || '',   // New Snapshot
      partyAadhar: party?.aadharNumber || '', // New Snapshot
      date: invoiceDate,
      items,
      subTotal: subTotalInclusive,
      taxPercent: 0, 
      taxAmount: totalCGST + totalSGST,
      globalDiscount: globalDiscount,
      grandTotal: grandTotal, 
      vehicleNumber: vehicleNo,
      poNumber: strictTotalQty.toString() // Force Accurate Qty
    };
  };

  const handleSaveInvoice = async () => {
    const invoice = generateInvoiceData();
    if (!invoice) return;

    setIsSaving(true);

    if (initialData) {
       // UPDATE Mode
       Store.updateInvoice(invoice);
    } else {
       // CREATE Mode
       Store.saveInvoice(invoice);
    }

    // NON-BLOCKING SYNC: Fire and forget to make UI faster
    if (hasCloudConfig) {
       Cloud.syncInvoice(invoice).catch(err => console.error("Background sync failed", err));
    }

    setIsSaving(false);

    setLastInvoice(invoice);

    // DIRECTLY OPEN PREVIEW (No more Copies Popup)
    setIsPreviewOpen(true);

    // Reset Form logic...
    if (!initialData) {
        setItems([]);
        setSelectedPartyId('');
        setVehicleNo('');
        setRefNo('');
        setGlobalDiscount(0);
        setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
    }

    onInvoiceSaved();
  };

  const handlePrint = () => {
    window.print();
  };

  const handleDownloadAll = () => {
    const csv = exportInvoicesToCSV(Store.getInvoices());
    const date = new Date().toISOString().split('T')[0];
    const encodedUri = encodeURI("data:text/csv;charset=utf-8," + csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Greenzar_Invoices_${date}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const selectedParty = parties.find(p => p.id === selectedPartyId);

  return (
    <div className="flex flex-col lg:flex-row h-[calc(100vh-64px)] overflow-hidden relative">

      {/* Preview Modal */}
      {isPreviewOpen && lastInvoice && (
        <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-md flex flex-col">
           <div className="flex justify-between items-center p-4 text-white">
              <h2 className="text-lg font-bold">Invoice Preview</h2>
              <div className="flex gap-3">
                 <button 
                  onClick={handlePrint} 
                  className="bg-sky-600 hover:bg-sky-500 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 transition-colors shadow-lg"
                 >
                    <Printer size={18} /> Print Invoice
                 </button>
                 <button onClick={() => setIsPreviewOpen(false)} className="bg-slate-800 hover:bg-slate-700 text-white px-3 py-2 rounded-lg transition-colors">
                    <X size={20} />
                 </button>
              </div>
           </div>
           <div className="flex-1 overflow-y-auto p-4 md:p-8 flex justify-center bg-slate-800">
              <div className="print-only-container shadow-2xl scale-100 origin-top bg-white">
                 <InvoiceTemplate invoice={lastInvoice} parties={parties} />
              </div>
           </div>
           <style>{`
             @media print {
               body * { visibility: hidden; }
               .print-only-container, .print-only-container * { visibility: visible; }
               .print-only-container { position: absolute; left: 0; top: 0; width: 100%; height: 100%; margin: 0; padding: 0; box-shadow: none; }
               @page { size: A4; margin: 0; }
             }
           `}</style>
        </div>
      )}

      {/* Quick Add Party Modal */}
      {isPartyModalOpen && (
        <div className="absolute inset-0 z-50 bg-black/50 flex items-center justify-center p-4 backdrop-blur-sm">
           <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm animate-in zoom-in duration-200">
              <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-slate-800">
                <User className="text-sky-600" /> New Customer
              </h3>
              <form onSubmit={handleCreateParty}>
                <label className="block text-sm font-medium text-slate-700 mb-1">Party Name</label>
                <input 
                  autoFocus
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 mb-4 focus:ring-2 focus:ring-sky-500 outline-none bg-white text-slate-900"
                  value={newPartyName}
                  onChange={e => setNewPartyName(e.target.value)}
                  placeholder="e.g. John Doe Enterprises"
                />
                <div className="flex justify-end gap-2">
                  <button type="button" onClick={() => setIsPartyModalOpen(false)} className="px-4 py-2 text-slate-500 hover:bg-slate-50 rounded-lg">Cancel</button>
                  <button type="submit" className="px-4 py-2 bg-sky-600 text-white rounded-lg hover:bg-sky-700 font-bold">Create</button>
                </div>
              </form>
           </div>
        </div>
      )}

      {/* Left: Invoice Builder */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-50">
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6 relative">
          {/* Header Gradient - Now with rounded-t-xl since overflow is visible */}
          <div className={`absolute top-0 left-0 w-full h-1 ${initialData ? 'bg-gradient-to-r from-orange-400 to-red-500' : 'bg-gradient-to-r from-slate-700 to-slate-900'} rounded-t-xl`}></div>

          <div className="flex justify-between items-center mb-4">
            <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
              {initialData ? <Edit3 className="text-orange-500" /> : <FileText className="text-slate-700" />}
              {initialData ? 'Edit Invoice' : 'Invoice Details'}
              {initialData && (
              <span className="text-[10px] font-bold bg-orange-100 text-orange-700 px-2 py-1 rounded border border-orange-200">
                EDIT MODE
              </span>
              )}
            </h2>

            <button
               onClick={handleDownloadAll}
               className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors border border-slate-200"
               title="Export All Invoices to CSV"
            >
               <FileSpreadsheet size={14} /> Download All (CSV)
            </button>
          </div>

          {/* Header Controls */}
          <div className="space-y-4 mb-6">
             {/* Party Select & Details */}
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Select Customer</label>
                  <div className="flex gap-2">
                    <select
                      value={selectedPartyId}
                      onChange={(e) => {
                         setSelectedPartyId(e.target.value);
                         setTimeout(() => invoiceNoInputRef.current?.focus(), 100);
                      }}
                      onKeyDown={(e) => handleGenericKeyDown(e, invoiceNoInputRef)}
                      className="w-full pl-3 pr-4 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 outline-none bg-white font-medium text-slate-700"
                    >
                      <option value="">-- Choose Customer --</option>
                      {parties.map(p => (
                        <option key={p.id} value={p.id}>{p.name}</option>
                      ))}
                    </select>
                    <button 
                      onClick={() => setIsPartyModalOpen(true)}
                      className="bg-slate-50 hover:bg-slate-100 text-slate-700 border border-slate-200 p-2.5 rounded-lg transition-colors"
                      title="Quick Add Party"
                    >
                      <Plus size={20} />
                    </button>
                  </div>
                </div>

                {/* Invoice No, Vehicle & Date */}
                <div className="grid grid-cols-3 gap-3">
                   <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Invoice No</label>
                    <input 
                      ref={invoiceNoInputRef}
                      type="text" 
                      value={customInvoiceNo}
                      onChange={(e) => setCustomInvoiceNo(e.target.value)}
                      onKeyDown={(e) => handleGenericKeyDown(e, vehicleInputRef)}
                      className="w-full px-3 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 outline-none text-slate-700 font-bold bg-white"
                    />
                  </div>
                  <div className="relative">
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Vehicle No</label>
                    <div className="relative">
                       <input
                        ref={vehicleInputRef}
                        type="text"
                        value={vehicleNo}
                        onChange={(e) => {
                          setVehicleNo(e.target.value);
                          setShowVehicleSuggestions(true);
                          setVehicleHighlightIndex(0);
                        }}
                        onFocus={() => setShowVehicleSuggestions(true)}
                        onBlur={() => setTimeout(() => setShowVehicleSuggestions(false), 200)}
                        onKeyDown={handleVehicleKeyDown}
                        placeholder="Type or Select..."
                        className="w-full pl-3 pr-8 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 outline-none bg-white text-slate-900 font-medium"
                       />
                       <div className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
                         {showVehicleSuggestions ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                       </div>
                    </div>
                    {/* Custom Dropdown for Vehicle */}
                    {showVehicleSuggestions && (
                      <ul className="absolute z-50 w-full bg-white border border-slate-200 rounded-lg shadow-xl mt-1 max-h-48 overflow-y-auto left-0">
                         {filteredVehicles.map((v, idx) => (
                           <li 
                            key={v}
                            onMouseDown={() => {
                              setVehicleNo(v);
                              setShowVehicleSuggestions(false);
                              productInputRef.current?.focus();
                            }}
                            className={`px-4 py-2 text-sm cursor-pointer ${idx === vehicleHighlightIndex ? 'bg-sky-100 text-sky-800 font-bold' : 'text-slate-700 hover:bg-slate-50'}`}
                           >
                             {v}
                           </li>
                         ))}
                         {filteredVehicles.length === 0 && (
                           <li className="px-4 py-2 text-xs text-slate-400 italic">No matches, press Enter to keep typing</li>
                         )}
                      </ul>
                    )}
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Date</label>
                    <input 
                      type="date" 
                      value={invoiceDate}
                      onChange={(e) => setInvoiceDate(e.target.value)}
                      className="w-full px-3 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 outline-none text-slate-900 bg-white"
                    />
                  </div>
                </div>
             </div>

             {/* Selected Party Details Card */}
             {selectedParty && (
               <div className="bg-slate-50 border border-slate-200 rounded-lg p-3 flex flex-wrap gap-4 text-sm animate-in fade-in slide-in-from-top-2">
                  <div className="flex items-center gap-2 text-slate-700">
                     <MapPin size={16} className="text-slate-500" />
                     <span className="truncate max-w-[200px]">{selectedParty.address}, {selectedParty.city}</span>
                  </div>
                  {selectedParty.phone && (
                    <div className="flex items-center gap-2 text-slate-700">
                       <Phone size={16} className="text-slate-500" />
                       <span>{selectedParty.phone}</span>
                    </div>
                  )}
                  {selectedParty.gstNumber && (
                    <div className="flex items-center gap-2 text-slate-700 bg-white px-2 rounded border border-slate-200">
                       <span className="font-bold text-xs text-slate-600">GST</span>
                       <span className="font-mono">{selectedParty.gstNumber}</span>
                    </div>
                  )}
               </div>
             )}
          </div>

          {/* Manual Entry Form */}
          <div className="border-t border-slate-100 pt-6">
              <h3 className="text-sm font-bold text-slate-700 mb-3 flex items-center gap-2">
                 <ShoppingCart size={18} className="text-slate-600" /> Items
              </h3>
              <form onSubmit={addItem} className="grid grid-cols-12 gap-3 items-end bg-slate-50 p-4 rounded-xl border border-slate-200">
                <div className="col-span-12 md:col-span-5 relative">
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Product (Type to Search)</label>
                  <input
                    ref={productInputRef}
                    value={productSearch}
                    onChange={handleProductSearchChange}
                    onFocus={() => setShowProductSuggestions(true)}
                    onBlur={() => setTimeout(() => setShowProductSuggestions(false), 200)}
                    onKeyDown={handleProductKeyDown}
                    placeholder="Start typing product name..."
                    className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-slate-500 outline-none bg-white text-slate-900 text-sm placeholder-slate-400"
                    disabled={!selectedPartyId}
                    autoComplete="off"
                  />
                  {/* Custom Dropdown for Product */}
                   {showProductSuggestions && (
                      <ul className="absolute z-[60] w-full bg-white border border-slate-200 rounded-lg shadow-xl mt-1 max-h-60 overflow-y-auto left-0">
                         {filteredProducts.map((p, idx) => (
                           <li 
                            key={p.id}
                            onMouseDown={() => selectProduct(p)}
                            className={`px-4 py-2 text-sm cursor-pointer flex justify-between ${idx === productHighlightIndex ? 'bg-sky-100 text-sky-800' : 'text-slate-700 hover:bg-slate-50'}`}
                           >
                             <span className={idx === productHighlightIndex ? 'font-bold' : ''}>{p.name}</span>
                             <span className="text-xs text-slate-400 font-mono">₹{p.standardRate}</span>
                           </li>
                         ))}
                         {filteredProducts.length === 0 && (
                           <li className="px-4 py-2 text-xs text-slate-400 italic">No matches found</li>
                         )}
                      </ul>
                    )}
                </div>

                <div className="col-span-4 md:col-span-3">
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Rate (Incl. Tax)</label>
                  <input 
                    type="number" 
                    step="0.01"
                    value={currentRate}
                    onChange={(e) => {
                      setCurrentRate(parseFloat(e.target.value));
                      setOverrideRate(true);
                    }}
                    onKeyDown={(e) => handleGenericKeyDown(e, qtyInputRef)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-slate-500 outline-none text-sm font-mono bg-white text-slate-900"
                  />
                </div>

                <div className="col-span-4 md:col-span-2">
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Qty</label>
                  <input 
                    ref={qtyInputRef}
                    type="number" 
                    min="1"
                    value={currentQty}
                    onChange={(e) => setCurrentQty(parseInt(e.target.value))}
