                    className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-slate-500 outline-none text-sm font-mono bg-white text-slate-900"
                  />
                </div>

                <div className="col-span-12 md:col-span-2">
                  <button 
                    ref={addBtnRef}
                    type="submit" 
                    disabled={!selectedPartyId || !currentProductId}
                    className="w-full bg-slate-800 hover:bg-slate-900 disabled:bg-slate-300 text-white py-2 rounded-md text-sm font-bold transition-colors flex justify-center items-center gap-2 h-[38px]"
                  >
                    Add
                  </button>
                </div>
              </form>
          </div>
        </div>

        {/* Line Items Table */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
