              <tr>
                <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Product</th>
                <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider text-right">GST %</th>
                <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider text-right">Rate (Incl.)</th>
                <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider text-center">Qty</th>
                <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider text-right">Total</th>
