            </thead>
            <tbody className="divide-y divide-slate-100">
              {items.map(item => (
                <tr key={item.id} className="hover:bg-slate-50 animate-in fade-in">
                  <td className="px-6 py-4">
                     <div className="font-semibold text-slate-800">{item.productName}</div>
                     {item.hsn && <div className="text-[10px] text-slate-400 font-mono">HSN: {item.hsn}</div>}
                  </td>
                  <td className="px-6 py-4 text-right text-slate-600 text-sm">{item.gstPercent ? `${item.gstPercent}%` : '-'}</td>
                  <td className="px-6 py-4 text-right text-slate-600 font-mono text-sm">₹{item.rate.toFixed(2)}</td>
                  <td className="px-6 py-4 text-center text-slate-800 font-bold bg-slate-50/50">{item.quantity}</td>
