import React, { useState, useEffect, useCallback } from 'react';
import { Party, Product, SpecialRate } from '../types';
import { Users, Search, Check, ArrowRight, Save, Download, CloudLightning, X } from 'lucide-react';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (r: SpecialRate[]) => void;
}

export const RateManager: React.FC<Props> = ({ parties, products, specialRates, setSpecialRates }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string | null>(null);
  const [filterText, setFilterText] = useState('');
  const [partySearch, setPartySearch] = useState('');

  // Local temporary state for inputs to allow smooth typing
  const [draftRates, setDraftRates] = useState<Record<string, number>>({});
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'pending'>('saved');

  // Load rates into draft state when party changes
  useEffect(() => {
    if (selectedPartyId) {
      const partyRates = specialRates.filter(r => r.partyId === selectedPartyId);
      const rateMap: Record<string, number> = {};
      partyRates.forEach(r => {
        rateMap[r.productId] = r.rate;
      });
      setDraftRates(rateMap);
      setSaveStatus('saved');
    } else {
      setDraftRates({});
    }
  }, [selectedPartyId, specialRates]); // Added specialRates to refresh if they change externally

  // Debounce logic for Auto-Saving
  useEffect(() => {
    if (!selectedPartyId || saveStatus !== 'pending') return;

    const timer = setTimeout(() => {
        setSaveStatus('saving');

        // Use current specialRates (latest state) to preserve other parties' data
        const otherRates = specialRates.filter(r => r.partyId !== selectedPartyId);

        const newPartyRates = Object.entries(draftRates).map(([prodId, rate]) => ({
            partyId: selectedPartyId,
            productId: prodId,
            rate: rate
        }));

        setSpecialRates([...otherRates, ...newPartyRates]);
        setSaveStatus('saved');

    }, 800); // Faster save

    return () => clearTimeout(timer);
  }, [draftRates, selectedPartyId, saveStatus, specialRates, setSpecialRates]);

  const handleRateChange = (productId: string, newValue: string) => {
    if (!selectedPartyId || !productId) return;

    setSaveStatus('pending');

    const numValue = parseFloat(newValue);
    const newDraft = { ...draftRates };

    if (!isNaN(numValue) && newValue !== '') {
      newDraft[productId] = numValue;
    } else {
      delete newDraft[productId];
    }
    setDraftRates(newDraft);
  };

  const exportToCSV = () => {
    if (!selectedPartyId) return;
    const party = parties.find(p => p.id === selectedPartyId);
    if (!party) return;

    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += "Product Name,Product Code,Standard Rate,Special Rate\n";

    products.forEach(p => {
      const rate = draftRates[p.id] || '';
      const name = p.name.includes(',') ? `"${p.name}"` : p.name;
      csvContent += `${name},${p.code},${p.standardRate},${rate}\n`;
    });

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Rates_${party.name.replace(/\s+/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const selectedParty = parties.find(p => p.id === selectedPartyId);

  const filteredProducts = products.filter(p => 
    (p.name && p.name.toLowerCase().includes(filterText.toLowerCase())) || 
    (p.code && p.code.toLowerCase().includes(filterText.toLowerCase()))
  );

  const filteredParties = parties.filter(p => 
    p.name.toLowerCase().includes(partySearch.toLowerCase())
  );

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden">
      {/* Sidebar: Party Selection */}
      <div className="w-1/3 min-w-[300px] border-r border-slate-200 bg-white flex flex-col">
        <div className="p-4 border-b border-slate-100 bg-slate-50/50">
          <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2 mb-3">
            <Users size={20} className="text-sky-600" /> Select Party
          </h2>

          {/* Party Search */}
          <div className="relative">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
             <input 
               type="text" 
               placeholder="Search customers..." 
               value={partySearch}
               onChange={(e) => setPartySearch(e.target.value)}
               className="w-full pl-9 pr-8 py-2 text-sm border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none bg-white text-slate-800"
             />
             {partySearch && (
               <button 
                onClick={() => setPartySearch('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
               >
                 <X size={14} />
               </button>
             )}
          </div>
        </div>

        <div className="overflow-y-auto flex-1 p-2 space-y-1">
          {filteredParties.map(party => {
            const isActive = selectedPartyId === party.id;
            const hasStoredRates = specialRates.some(r => r.partyId === party.id);

            return (
              <button
                key={party.id}
                onClick={() => setSelectedPartyId(party.id)}
                className={`w-full text-left px-4 py-3 rounded-lg flex justify-between items-center transition-all ${
                  isActive 
                    ? 'bg-sky-50 border-sky-200 ring-1 ring-sky-100 shadow-sm' 
                    : 'hover:bg-slate-50 border border-transparent'
                }`}
              >
                <div>
                  <div className={`font-medium ${isActive ? 'text-sky-900' : 'text-slate-700'}`}>
                    {party.name}
                  </div>
                  {hasStoredRates && (
                    <div className="text-[10px] bg-sky-100 text-sky-700 px-2 py-0.5 rounded-full inline-block mt-1 font-bold">
                      Custom Rates Active
                    </div>
                  )}
                </div>
                {isActive && <ArrowRight size={16} className="text-sky-600" />}
              </button>
            );
          })}
          {filteredParties.length === 0 && (
             <div className="p-4 text-center text-slate-400 text-sm">
               No parties found.
             </div>
          )}
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 bg-slate-50 flex flex-col relative">
        {selectedParty ? (
          <>
            <div className="p-6 bg-white border-b border-slate-200 shadow-sm space-y-4">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-2xl font-bold text-slate-800">Price List: {selectedParty.name}</h2>
                  <p className="text-slate-500 text-sm mt-1">
                    Changes are saved automatically.
                  </p>
                </div>
                <div className="flex gap-2 items-center">
                   <button 
                    onClick={exportToCSV}
                    className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-sky-700 bg-sky-50 hover:bg-sky-100 rounded-lg transition-colors border border-sky-200"
                    title="Download as CSV"
                   >
                     <Download size={16} /> Export
                   </button>

                   <div className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                     saveStatus === 'saved' ? 'text-slate-400 bg-slate-100' : 
                     saveStatus === 'saving' ? 'text-blue-600 bg-blue-50' :
                     'text-orange-500 bg-orange-50'
                   }`}>
                      {saveStatus === 'saved' && <><Check size={16} /> Saved</>}
                      {saveStatus === 'saving' && <><CloudLightning size={16} className="animate-pulse" /> Saving...</>}
                      {saveStatus === 'pending' && <>Typing...</>}
                   </div>
                </div>
              </div>

              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="Search products..."
                  value={filterText}
                  onChange={(e) => setFilterText(e.target.value)}
                  className="pl-10 pr-4 py-2 border border-slate-300 rounded-lg text-sm w-full focus:ring-2 focus:ring-sky-500 outline-none"
                />
                {filterText && (
                   <button 
                    onClick={() => setFilterText('')}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                   >
                     <X size={14} />
                   </button>
                 )}
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-6">
              <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <table className="w-full text-left border-collapse">
                  <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                    <tr>
                      <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider w-1/2">Product</th>
                      <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider text-right w-1/4">Standard</th>
                      <th className="px-6 py-4 font-bold text-sky-700 text-xs uppercase tracking-wider w-1/4">
                        Special Rate
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {filteredProducts.map(product => {
                      const currentVal = draftRates[product.id];
                      const isCustom = currentVal !== undefined;

                      return (
                        <tr key={product.id} className={`hover:bg-slate-50 transition-colors ${isCustom ? 'bg-sky-50/30' : ''}`}>
                          <td className="px-6 py-4">
                            <div className="font-medium text-slate-800">{product.name}</div>
                            <div className="text-xs text-slate-400">{product.code}</div>
                          </td>
                          <td className="px-6 py-4 text-right">
                            <span className="text-slate-500">₹{product.standardRate.toFixed(2)}</span>
                          </td>
                          <td className="px-6 py-4">
                            <div className="relative">
                              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">₹</span>
                              <input 
                                type="number"
                                step="0.01"
                                placeholder="Standard"
                                className={`w-full pl-8 pr-3 py-2 border rounded-lg focus:ring-2 focus:ring-sky-500 outline-none transition-all ${
                                  isCustom 
                                    ? 'border-sky-500 bg-white font-bold text-sky-700 shadow-sm' 
                                    : 'border-slate-200 bg-slate-50 text-slate-500'
                                }`}
                                value={currentVal ?? ''}
                                onChange={(e) => handleRateChange(product.id, e.target.value)}
                              />
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                    {filteredProducts.length === 0 && (
                      <tr>
                        <td colSpan={3} className="px-6 py-12 text-center text-slate-400">
                          No products found.
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
            <Users size={64} className="mb-4 opacity-20" />
            <p className="text-lg font-medium">Select a party to manage rates</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Product } from '../types';
import { Plus, Trash2, Edit2, Package, Tag, CloudLightning, Search, X } from 'lucide-react';

interface Props {
  products: Product[];
  setProducts: (p: Product[]) => void;
}

export const ProductManager: React.FC<Props> = ({ products, setProducts }) => {
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<Product>>({});
  const [searchTerm, setSearchTerm] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || formData.standardRate === undefined) return;

    let updatedProducts = [...products];

    if (editingId) {
      updatedProducts = products.map(p => p.id === editingId ? { ...p, ...formData } as Product : p);
    } else {
      const newProduct: Product = {
        id: crypto.randomUUID(),
        name: formData.name!,
        code: formData.code || 'N/A',
        standardRate: Number(formData.standardRate),
        unit: formData.unit || 'pcs',
        hsn: formData.hsn || '',
        gstPercent: Number(formData.gstPercent) || 0,
        qtyPerCase: Number(formData.qtyPerCase) || 1
      };
      updatedProducts.push(newProduct);
    }

    setProducts(updatedProducts);
    closeForm();
  };

  const deleteProduct = (id: string) => {
    if (confirm('Are you sure? This will remove the product.')) {
      setProducts(products.filter(p => p.id !== id));
    }
  };

  const openEdit = (product: Product) => {
    setFormData(product);
    setEditingId(product.id);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setFormData({});
    setEditingId(null);
    setIsFormOpen(false);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.code.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="p-6 max-w-6xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Products & Services</h2>
          <p className="text-slate-500">Manage items, tax info, and case quantities.</p>
        </div>

        <div className="flex items-center gap-3 w-full md:w-auto">
          {/* Search Bar */}
          <div className="relative flex-1 md:w-64">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
             <input 
               type="text" 
               placeholder="Search products..." 
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
               className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none bg-white text-slate-900 shadow-sm"
             />
             {searchTerm && (
               <button 
                onClick={() => setSearchTerm('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
               >
                 <X size={14} />
               </button>
             )}
          </div>

          <button 
            onClick={() => setIsFormOpen(true)}
            className="bg-sky-600 hover:bg-sky-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors font-medium whitespace-nowrap"
          >
            <Plus size={18} /> Add Product
          </button>
        </div>
      </div>

      {isFormOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl p-6 w-full max-w-lg animate-in fade-in zoom-in duration-200 overflow-y-auto max-h-[90vh]">
            <h3 className="text-xl font-bold mb-4">{editingId ? 'Edit Product' : 'New Product'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">

              {/* Basic Info */}
              <div className="bg-slate-50 p-3 rounded-lg space-y-3">
                <h4 className="text-xs font-bold text-slate-400 uppercase">Basic Details</h4>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Product Name *</label>
                  <input 
                    autoFocus
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-sky-500 outline-none"
                    value={formData.name || ''}
                    onChange={e => setFormData({...formData, name: e.target.value})}
                    required
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Code/SKU</label>
                    <input 
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-sky-500 outline-none"
                      value={formData.code || ''}
                      onChange={e => setFormData({...formData, code: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Standard Rate (₹) *</label>
                    <input 
                      type="number" step="0.01"
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-sky-500 outline-none"
                      value={formData.standardRate || ''}
