                      className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-sky-500 outline-none"
                      value={formData.hsn || ''}
                      onChange={e => setFormData({...formData, hsn: e.target.value})}
                      placeholder="e.g. 8471"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">GST (%)</label>
                    <input 
                      type="number"
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-sky-500 outline-none"
                      value={formData.gstPercent || ''}
                      onChange={e => setFormData({...formData, gstPercent: parseFloat(e.target.value)})}
                      placeholder="e.g. 18"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Qty Per Case</label>
                    <input 
                      type="number"
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-sky-500 outline-none"
                      value={formData.qtyPerCase || ''}
                      onChange={e => setFormData({...formData, qtyPerCase: parseFloat(e.target.value)})}
                      placeholder="e.g. 12"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Unit</label>
                    <input 
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-sky-500 outline-none"
                      value={formData.unit || ''}
                      onChange={e => setFormData({...formData, unit: e.target.value})}
                      placeholder="pcs"
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={closeForm} className="text-slate-500 hover:text-slate-700 px-4 py-2">Cancel</button>
                <button type="submit" className="bg-sky-600 hover:bg-sky-700 text-white px-6 py-2 rounded-lg">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Product Info</th>
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Tax & Specs</th>
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider text-right">Standard Rate</th>
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredProducts.map(product => (
              <tr key={product.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4">
                  <div className="flex items-center gap-3">
                    <div className="bg-sky-100 p-2 rounded-lg text-sky-600">
                      <Package size={20} />
                    </div>
                    <div>
                      <div className="font-semibold text-slate-800">{product.name}</div>
                      <div className="text-xs text-slate-500 font-mono">SKU: {product.code}</div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="text-xs text-slate-600 space-y-1">
                    <div>HSN: <span className="font-mono font-medium">{product.hsn || '-'}</span></div>
                    <div>GST: <span className="font-mono font-medium">{product.gstPercent || 0}%</span></div>
                    <div>Case: <span className="font-mono font-medium">{product.qtyPerCase || 1} {product.unit}</span></div>
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="inline-flex items-center gap-1 font-mono text-slate-700 bg-slate-100 px-2 py-1 rounded">
                    <span className="text-slate-400">₹</span>
                    {product.standardRate.toFixed(2)}
                  </div>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-2">
                    <button onClick={() => openEdit(product)} className="text-slate-400 hover:text-sky-600 p-2 hover:bg-sky-50 rounded-full transition-colors"><Edit2 size={16} /></button>
                    <button onClick={() => deleteProduct(product.id)} className="text-slate-400 hover:text-red-500 p-2 hover:bg-red-50 rounded-full transition-colors"><Trash2 size={16} /></button>
                  </div>
                </td>
              </tr>
            ))}
            {filteredProducts.length === 0 && (
              <tr>
                <td colSpan={4} className="px-6 py-12 text-center text-slate-400">
                  <Package size={48} className="mx-auto mb-3 opacity-20" />
                  <p>{searchTerm ? 'No products match your search.' : 'No products added yet.'}</p>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Users, Package, DollarSign, FileText, History, Menu, X, Database, CloudLightning, CheckCircle, RefreshCw, Loader2, LayoutDashboard, Printer, LogOut, User as UserIcon, ArrowUpCircle, Edit3, Download, MoreHorizontal, FileDown, Search } from 'lucide-react';
import { PartyManager } from './components/PartyManager';
import { ProductManager } from './components/ProductManager';
import { RateManager } from './components/RateManager';
import { Billing } from './components/Billing';
import { DataManager } from './components/DataManager';
import { UserManager } from './components/UserManager';
import { MoreMenu } from './components/MoreMenu';
import { Login } from './components/Login';
import { Store } from './services/store';
import { Cloud } from './services/cloud';
import { Party, Product, SpecialRate, Invoice, ViewState, User } from './types';
import { InvoiceTemplate } from './components/InvoiceTemplate';
import { exportInvoicesToCSV } from './services/csv';

// Declare html2pdf for TypeScript
declare global {
  interface Window {
    html2pdf: any;
  }
}

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // State
  const [validUsers, setValidUsers] = useState<User[]>(() => Store.getUsers());
  const [parties, setParties] = useState<Party[]>(() => Store.getParties());
  const [products, setProducts] = useState<Product[]>(() => Store.getProducts());
  const [specialRates, setSpecialRates] = useState<SpecialRate[]>(() => Store.getRates());
  const [invoices, setInvoices] = useState<Invoice[]>(() => Store.getInvoices());

  // UI State
  const [currentView, setCurrentView] = useState<ViewState>('billing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  // Search State for History View
  const [invoiceSearch, setInvoiceSearch] = useState('');

  // Context Menu State
  const [contextMenu, setContextMenu] = useState<{ visible: boolean; x: number; y: number; invoice: Invoice | null }>({
    visible: false,
    x: 0,
    y: 0,
    invoice: null,
  });

  // PDF Download State
  const [pdfInvoice, setPdfInvoice] = useState<Invoice | null>(null);
  const pdfContainerRef = useRef<HTMLDivElement>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Sync Status
  const [cloudUrl, setCloudUrl] = useState(() => Cloud.getScriptUrl());
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');

  const isFirstLoad = useRef(true);
  const hasPendingChanges = useRef(false);
  // This ref tracks if the current state change was caused by a Cloud Pull
  // If true, we skip the next Auto-Push to prevent overwriting the sheet with what we just downloaded
  const isRemoteUpdate = useRef(false);
  const lastPushTime = useRef(0); 

  const loadLocalData = () => {
    setParties(Store.getParties());
    setProducts(Store.getProducts());
    setSpecialRates(Store.getRates());
    setInvoices(Store.getInvoices());
    setValidUsers(Store.getUsers());
  };

  // Close context menu on click elsewhere
  useEffect(() => {
    const handleClick = () => setContextMenu({ ...contextMenu, visible: false });
    window.addEventListener('click', handleClick);
    return () => window.removeEventListener('click', handleClick);
  }, [contextMenu]);

  // Auto-Print Effect when History Preview Opens
  useEffect(() => {
    if (viewInvoice) {
      // Increased delay to 1000ms to ensure QR code image loads before print dialog
      const timer = setTimeout(() => {
        window.print();
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [viewInvoice]);

  // Handle PDF Generation
  useEffect(() => {
    if (pdfInvoice && pdfContainerRef.current && !isGeneratingPdf) {
      setIsGeneratingPdf(true);
      // Wait for render
      setTimeout(() => {
        const element = pdfContainerRef.current;
        if (!element || !window.html2pdf) {
            setIsGeneratingPdf(false);
            setPdfInvoice(null);
            return;
        }

        const opt = {
          margin: 0,
          filename: `Invoice_${pdfInvoice.invoiceNumber}.pdf`,
          image: { type: 'jpeg', quality: 0.98 },
          html2canvas: { scale: 2, useCORS: true },
          jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        window.html2pdf().set(opt).from(element).save().then(() => {
          setIsGeneratingPdf(false);
          setPdfInvoice(null);
        }).catch((err: any) => {
          console.error('PDF Generation Error:', err);
          setIsGeneratingPdf(false);
          setPdfInvoice(null);
        });
      }, 500); // Wait for QR code and layout
    }
  }, [pdfInvoice, isGeneratingPdf]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) {
      setIsAuthenticated(true);
    }
    if (cloudUrl) {
      Cloud.fetchUsers().then(cloudUsers => {
        if (cloudUsers.length > 1) { 
          setValidUsers(cloudUsers);
          Store.saveUsers(cloudUsers);
        }
      });
    }
  }, []);

  // --- AUTO-PUSH (App -> Sheet) ---
  useEffect(() => {
    Store.saveParties(parties);
    Store.saveProducts(products);
    Store.saveRates(specialRates);
    Store.saveUsers(validUsers);

    if (isFirstLoad.current) {
      isFirstLoad.current = false;
      return;
    }

    // SAFETY GUARD: Never push empty data automatically. 
    if (parties.length === 0 && products.length === 0) return;

    // REMOTE UPDATE CHECK:
    // If this change came from the Cloud (Pull), do NOT push it back.
    if (isRemoteUpdate.current) {
       isRemoteUpdate.current = false; // Reset flag
       return; 
    }

    hasPendingChanges.current = true;

    if (cloudUrl) {
      setSyncStatus('syncing');

      const handler = setTimeout(async () => {
         try {
           await Cloud.syncMasterData(parties, products, specialRates, validUsers);
           lastPushTime.current = Date.now();
           setSyncStatus('synced');
           hasPendingChanges.current = false;
           setTimeout(() => setSyncStatus('idle'), 2000);
         } catch (e) {
           console.error("Auto-sync failed", e);
           setSyncStatus('idle');
           hasPendingChanges.current = false; 
         }
      }, 2000); 

      return () => clearTimeout(handler);
    } else {
       hasPendingChanges.current = false;
    }
  }, [parties, products, specialRates, validUsers, cloudUrl]);

  // --- MANUAL FORCE PUSH ---
  const handleForcePush = async () => {
      if (!cloudUrl) return;
      setSyncStatus('syncing');
      try {
          console.log("Force Pushing Data...");
          await Cloud.syncMasterData(parties, products, specialRates, validUsers);
          lastPushTime.current = Date.now();
          setSyncStatus('synced');
          hasPendingChanges.current = false;
          setTimeout(() => setSyncStatus('idle'), 2000);
          alert("Data successfully uploaded to Google Sheet.");
      } catch(e) {
          console.error(e);
          setSyncStatus('idle');
          alert("Upload failed. Check connection.");
      }
  };

  // --- PULL LOGIC (CRITICAL DATA PROTECTION) ---
  const handleCloudPull = useCallback(async () => {
      // Don't pull if user is actively typing (pending changes) or we are already syncing
      if (syncStatus === 'syncing' || syncStatus === 'pulling' || hasPendingChanges.current) return;
      if (Date.now() - lastPushTime.current < 10000) return; 

      if (!cloudUrl) return;

      try {
        setSyncStatus('pulling');

        const [cloudPartiesRaw, cloudProductsRaw, cloudRatesRaw, cloudInvoices, cloudUsers] = await Promise.all([
           Cloud.fetchData('PARTIES'),
           Cloud.fetchData('PRODUCTS'),
           Cloud.fetchData('RATES'),
           Cloud.fetchInvoices(),
           Cloud.fetchUsers()
        ]);

        // 1. Parse Cloud Data (Parties & Products First)
        const cloudParties: Party[] = cloudPartiesRaw.slice(1).map((r: any[]) => ({
          id: String(r[0]).trim() || `PTY-${Math.random().toString(36).substr(2,9)}`, 
          name: r[1], 
          address: r[2], city: r[3], phone: r[4], 
          gstNumber: r[5], aadharNumber: r[6], panNumber: r[7], email: ''
        })).filter((p: Party) => p.name); 

        const cloudProducts: Product[] = cloudProductsRaw.slice(1).map((r: any[]) => ({
          id: String(r[0]).trim() || `PRD-${Math.random().toString(36).substr(2,9)}`, 
          name: r[1], 
          code: r[2], hsn: r[3], gstPercent: Number(r[4]), 
          qtyPerCase: Number(r[5]), standardRate: Number(r[6]), unit: r[7]
        })).filter((p: Product) => p.name); 

        // If local changes happened while fetching, abort update to protect local work
        if (hasPendingChanges.current) {
           setSyncStatus('idle');
           return;
        }

        // 2. DECIDE MASTER: CLOUD IS MASTER
        // Logic: If Cloud has valid data, we accept it. 
        // We do NOT block it if local is bigger. We assume Cloud is the Truth.

        let finalParties = parties;
        let updateParties = false;

        if (cloudParties.length > 0 && JSON.stringify(cloudParties) !== JSON.stringify(parties)) {
             finalParties = cloudParties;
             updateParties = true;
        }

        let finalProducts = products;
        let updateProducts = false;

        if (cloudProducts.length > 0 && JSON.stringify(cloudProducts) !== JSON.stringify(products)) {
             finalProducts = cloudProducts;
             updateProducts = true;
        }

        // 3. PARSE RATES based on FINAL lists
        let finalRates = specialRates;
        let updateRates = false;

        if (cloudRatesRaw.length > 0) {
            let parsedRates: SpecialRate[] = [];
            const header = cloudRatesRaw[0]; 
            const partyColMap: Record<number, string> = {};

            // Map Columns to Party IDs from FINAL PARTIES list
            for(let i=3; i<header.length; i++) {
                const pName = header[i];
                const pObj = finalParties.find(p => p.name.trim().toLowerCase() === String(pName).trim().toLowerCase());
                if(pObj) partyColMap[i] = pObj.id;
            }

            for(let i=1; i<cloudRatesRaw.length; i++) {
                const row = cloudRatesRaw[i];
                const prodId = String(row[0]).trim();
                // Match against FINAL PRODUCTS list
                const matchedProduct = finalProducts.find(p => p.id === prodId) || finalProducts.find(p => p.name === row[1]);

                if(matchedProduct) {
                    Object.entries(partyColMap).forEach(([colIdx, partyId]) => {
                        const val = parseFloat(row[Number(colIdx)]);
                        if(!isNaN(val) && val > 0) {
                            parsedRates.push({ partyId, productId: matchedProduct.id, rate: val });
                        }
                    });
                }
            }

            if (parsedRates.length > 0 && JSON.stringify(parsedRates) !== JSON.stringify(specialRates)) {
                finalRates = parsedRates;
                updateRates = true;
            }
        }

        // 4. APPLY UPDATES
        // We set the flag IS_REMOTE_UPDATE to true to block the Auto-Push effect
        if (updateParties || updateProducts || updateRates) {
           isRemoteUpdate.current = true;
           if (updateParties) setParties(finalParties);
           if (updateProducts) setProducts(finalProducts);
           if (updateRates) setSpecialRates(finalRates);
        }

        if (cloudInvoices.length !== invoices.length) {
             setInvoices(cloudInvoices);
             Store.saveInvoices(cloudInvoices);
        }

        if (cloudUsers.length > 0 && JSON.stringify(cloudUsers) !== JSON.stringify(validUsers)) {
            setValidUsers(cloudUsers);
            Store.saveUsers(cloudUsers);
        }

        setSyncStatus('idle');

      } catch (e) {
        console.error("Cloud Pull Error", e);
        setSyncStatus('idle');
      }
  }, [parties, products, specialRates, invoices, validUsers, syncStatus, cloudUrl]);

  useEffect(() => {
    if (!cloudUrl) return;
    const interval = setInterval(handleCloudPull, 10000); 
    return () => clearInterval(interval);
  }, [handleCloudPull, cloudUrl]);

  const refreshInvoices = () => {
    setInvoices(Store.getInvoices());
  };

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setCurrentView('billing');
  };

  const handleDownloadSingleInvoice = (invoice: Invoice) => {
    const csv = exportInvoicesToCSV([invoice]);
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI("data:text/csv;charset=utf-8," + csv));
    link.setAttribute("download", `Invoice_${invoice.invoiceNumber}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrintOptions = (e: React.MouseEvent, invoice: Invoice) => {
    e.preventDefault();
    e.stopPropagation();
    setContextMenu({
      visible: true,
      x: e.pageX - 120, // Offset to appear nicely under/near cursor
      y: e.pageY,
      invoice: invoice
    });
  };

  const handleMenuAction = (action: 'print' | 'download') => {
    const inv = contextMenu.invoice;
    setContextMenu({ ...contextMenu, visible: false });

    if (inv) {
      if (action === 'print') {
        setViewInvoice(inv);
      } else if (action === 'download') {
        setPdfInvoice(inv);
      }
    }
  };

  const handleLogin = (user: User) => {
    setIsAuthenticated(true);
    sessionStorage.setItem('gfb_user', JSON.stringify(user));
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('gfb_user');
  };

  // Filter Logic for Invoice History
  const filteredInvoices = invoices.filter(inv => {
    const term = invoiceSearch.toLowerCase();
    return (
      inv.invoiceNumber.toLowerCase().includes(term) ||
      inv.partyName.toLowerCase().includes(term) ||
      (inv.vehicleNumber && inv.vehicleNumber.toLowerCase().includes(term))
    );
  });

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} validUsers={validUsers} />;
  }

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState; icon: any; label: string }) => (
    <button
      onClick={() => {
        setCurrentView(view);
        setEditingInvoice(null); // Clear editing state when changing views
        setIsMobileMenuOpen(false);
      }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium mb-1 ${
        currentView === view 
          ? 'bg-sky-100 text-sky-800 shadow-sm ring-1 ring-sky-200' 
          : 'text-slate-500 hover:bg-slate-50 hover:text-sky-600'
      }`}
    >
      <Icon size={18} strokeWidth={2} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">

      {/* Context Menu (Dropdown) */}
      {contextMenu.visible && (
        <div 
          className="fixed z-[999] bg-white border border-slate-200 shadow-xl rounded-lg py-1 w-40 animate-in fade-in zoom-in-95 duration-100 origin-top-left"
          style={{ top: contextMenu.y, left: Math.min(contextMenu.x, window.innerWidth - 170) }}
        >
          <button 
            onClick={() => handleMenuAction('print')}
            className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-sky-50 hover:text-sky-700 flex items-center gap-2"
          >
            <Printer size={14} /> Print
          </button>
          <button 
            onClick={() => handleMenuAction('download')}
            className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-sky-50 hover:text-sky-700 flex items-center gap-2"
          >
            <FileDown size={14} /> Download PDF
          </button>
        </div>
      )}

      {/* Hidden Container for PDF Generation */}
      {pdfInvoice && (
        <div className="fixed top-0 left-0 z-[-1] w-[210mm] opacity-0 pointer-events-none">
          <div ref={pdfContainerRef}>
            <InvoiceTemplate invoice={pdfInvoice} parties={parties} />
          </div>
        </div>
      )}

      {/* --- FLOATING SYNC STATUS WIDGET --- */}
      {cloudUrl && (
        <div className="fixed bottom-6 right-6 z-50 animate-in slide-in-from-bottom-5">
          <div className="bg-white rounded-xl shadow-lg border border-slate-100 p-3 pr-4 flex items-center gap-3 min-w-[180px]">
            {syncStatus === 'syncing' || syncStatus === 'pulling' ? (
              <RefreshCw className="text-orange-500 animate-spin" size={20} />
            ) : (
              <CheckCircle className="text-emerald-500" size={20} />
            )}

            <div className="flex-1">
              <div className={`font-bold text-xs ${syncStatus === 'syncing' || syncStatus === 'pulling' ? 'text-orange-600' : 'text-slate-700'}`}>
                {syncStatus === 'syncing' ? 'Syncing...' : 
                 syncStatus === 'pulling' ? 'Updating...' :
                 syncStatus === 'synced' ? 'All Saved' : 'Online'}
              </div>
            </div>

            <button 
              onClick={handleCloudPull} 
              className="p-1.5 hover:bg-slate-50 rounded-full text-slate-400 transition-colors"
              title="Force Refresh"
            >
              <RefreshCw size={14} className={syncStatus === 'pulling' ? 'animate-spin' : ''} />
            </button>
          </div>
        </div>
      )}

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 w-full bg-white z-50 border-b border-slate-200 px-4 py-3 flex justify-between items-center shadow-sm no-print">
        <div className="font-bold text-sky-700 text-lg flex items-center gap-2">
            <LayoutDashboard size={20} /> GREENZAR
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
            {isMobileMenuOpen ? <X /> : <Menu />}
          </button>
        </div>
      </div>

      {/* Sidebar Navigation */}
      <div className={`
        fixed md:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 z-40 shadow-xl md:shadow-none no-print
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0
      `}>
        <div className="p-6">
          <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2 tracking-tight">
            <div className="w-8 h-8 bg-sky-600 rounded-lg flex items-center justify-center text-white text-lg font-bold shadow-lg shadow-sky-200">G</div>
            GREENZAR
          </h1>
          <p className="text-[10px] text-slate-400 mt-2 uppercase tracking-wider font-bold pl-10">Food & Beverage</p>
        </div>

        <nav className="px-4 py-2">
          <NavItem view="billing" icon={FileText} label="Create Invoice" />
          <NavItem view="history" icon={History} label="History" />

          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Database</div>

          <NavItem view="parties" icon={Users} label="Parties" />
          <NavItem view="products" icon={Package} label="Products" />
          <NavItem view="rates" icon={DollarSign} label="Price Lists" />

          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Configuration</div>
          <NavItem view="users" icon={UserIcon} label="Users" />
          <NavItem view="data" icon={Database} label="Data & Sync" />
          <NavItem view="more" icon={MoreHorizontal} label="More" />
        </nav>

        {/* Simplified Sidebar Footer */}
        <div className="absolute bottom-0 left-0 w-full p-4 border-t border-slate-100 bg-slate-50/50 backdrop-blur-sm">
           <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2 text-xs font-bold text-slate-500 hover:text-red-600 hover:bg-red-50 p-2 rounded-lg transition-colors"
           >
