import { Search, Download, ChevronDown, ChevronUp, FileText, Package, Calendar, Truck, User } from 'lucide-react';
import { exportInvoicesToCSV } from '../services/csv';

interface Props {
  invoices: Invoice[];
}

export const InvoiceLogs: React.FC<Props> = ({ invoices }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const filteredInvoices = invoices.filter(inv =>
    inv.invoiceNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
    inv.partyName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (inv.vehicleNumber && inv.vehicleNumber.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const toggleExpand = (id: string) => {
    if (expandedId === id) setExpandedId(null);
    else setExpandedId(id);
  };

  const handleDownload = () => {
    const csv = exportInvoicesToCSV(filteredInvoices);
    const date = new Date().toISOString().split('T')[0];
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI("data:text/csv;charset=utf-8," + csv));
    link.setAttribute("download", `Invoice_Logs_${date}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="p-6 max-w-7xl mx-auto h-full flex flex-col">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <FileText className="text-slate-600" /> All Logs
          </h2>
          <p className="text-slate-500 text-sm">Comprehensive audit trail of all transactions.</p>
        </div>
        <button
          onClick={handleDownload}
          className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors font-medium shadow-sm"
        >
          <Download size={18} /> Download Filtered CSV
        </button>
      </div>

      <div className="mb-4 relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
        <input
          type="text"
          placeholder="Search logs by Invoice #, Party Name, or Vehicle..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
