import React, { useState, useMemo } from 'react';
import { Invoice, Party } from '../types';
import { Search, Trophy, Calendar, Filter, Download } from 'lucide-react';
import { exportInvoicesToCSV } from '../services/csv'; // We can reuse or make a new one

interface Props {
  invoices: Invoice[];
  parties: Party[];
}

export const Ranking: React.FC<Props> = ({ invoices, parties }) => {
  // Default to current month
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0];
  const lastDay = today.toISOString().split('T')[0];

  const [startDate, setStartDate] = useState(firstDay);
  const [endDate, setEndDate] = useState(lastDay);

  const topParties = useMemo(() => {
    const agg: Record<string, { partyId: string, partyName: string, total: number, count: number }> = {};

    invoices.forEach(inv => {
      if (inv.date >= startDate && inv.date <= endDate) {
        if (!agg[inv.partyId]) {
          agg[inv.partyId] = { 
             partyId: inv.partyId, 
             partyName: inv.partyName || 'Unknown', 
             total: 0, 
             count: 0 
          };
        }
        agg[inv.partyId].total += inv.grandTotal;
        agg[inv.partyId].count += 1;
      }
    });

    return Object.values(agg)
      .sort((a, b) => b.total - a.total)
      .slice(0, 10); // Top 10
  }, [invoices, startDate, endDate]);

  const handleDownload = () => {
     let csv = "Rank,Party Name,Invoice Count,Total Sales\n";
     topParties.forEach((p, idx) => {
         csv += `${idx + 1},"${p.partyName}",${p.count},${p.total}\n`;
     });

     const date = new Date().toISOString().split('T')[0];
     const link = document.createElement("a");
     link.setAttribute("href", encodeURI("data:text/csv;charset=utf-8," + csv));
     link.setAttribute("download", `Top10_Ranking_${date}.csv`);
     document.body.appendChild(link);
     link.click();
     document.body.removeChild(link);
  };

  return (
    <div className="p-6 max-w-5xl mx-auto">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Trophy className="text-yellow-500" /> Top 10 Ranking
          </h2>
          <p className="text-slate-500">Highest billing parties for the selected period.</p>
        </div>

        <button 
            onClick={handleDownload}
            disabled={topParties.length === 0}
            className="bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors font-medium shadow-sm"
        >
            <Download size={18} /> Export List
        </button>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-wrap gap-4 items-center">
         <div className="flex items-center gap-2 text-slate-500 font-bold uppercase text-xs mr-2">
            <Filter size={14} /> Filter Range
         </div>

         <div>
            <label className="block text-[10px] text-slate-400 font-bold uppercase mb-1">From Date</label>
            <input 
              type="date" 
              value={startDate} 
              onChange={e => setStartDate(e.target.value)}
              className="px-3 py-2 border border-slate-300 rounded-lg text-sm font-medium focus:ring-2 focus:ring-sky-500 outline-none"
            />
         </div>

         <div className="self-end pb-2 text-slate-400 font-bold">-</div>

         <div>
            <label className="block text-[10px] text-slate-400 font-bold uppercase mb-1">To Date</label>
            <input 
              type="date" 
              value={endDate} 
              onChange={e => setEndDate(e.target.value)}
              className="px-3 py-2 border border-slate-300 rounded-lg text-sm font-medium focus:ring-2 focus:ring-sky-500 outline-none"
            />
         </div>
      </div>

      {/* Ranking List */}
      <div className="bg-white rounded-xl shadow-lg border border-slate-100 overflow-hidden">
         <div className="grid grid-cols-12 bg-slate-50 border-b border-slate-200 px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">
             <div className="col-span-2 text-center">Rank</div>
             <div className="col-span-6">Party Name</div>
             <div className="col-span-2 text-center">Invoices</div>
             <div className="col-span-2 text-right">Total Sales</div>
         </div>

         <div className="divide-y divide-slate-100">
             {topParties.map((party, index) => {
                 let medalColor = "bg-slate-100 text-slate-500";
                 if (index === 0) medalColor = "bg-yellow-100 text-yellow-700 border border-yellow-200";
                 if (index === 1) medalColor = "bg-slate-200 text-slate-600 border border-slate-300";
                 if (index === 2) medalColor = "bg-orange-100 text-orange-700 border border-orange-200";

                 return (
                    <div key={party.partyId} className="grid grid-cols-12 px-6 py-4 items-center hover:bg-slate-50 transition-colors">
                        <div className="col-span-2 flex justify-center">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${medalColor}`}>
                                {index + 1}
                            </div>
                        </div>
                        <div className="col-span-6">
                            <div className="font-bold text-slate-800 text-base">{party.partyName}</div>
                            <div className="text-xs text-slate-400 font-mono">ID: {party.partyId.slice(0,8)}...</div>
                        </div>
                        <div className="col-span-2 text-center text-slate-600 font-medium">
                            {party.count}
                        </div>
                        <div className="col-span-2 text-right font-black text-slate-800 text-lg">
                            ₹{party.total.toLocaleString('en-IN')}
                        </div>
                    </div>
                 );
             })}

             {topParties.length === 0 && (
                 <div className="p-12 text-center text-slate-400 flex flex-col items-center">
                    <Trophy size={48} className="mb-4 opacity-20" />
                    <p>No billing data found for this date range.</p>
                 </div>
             )}
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Users, Package, DollarSign, FileText, History, Menu, X, Database, CloudLightning, CheckCircle, RefreshCw, Loader2, LayoutDashboard, Printer, LogOut, User as UserIcon, ArrowUpCircle, Edit3, Download, MoreHorizontal, FileDown, Search, ClipboardList, Trophy } from 'lucide-react';
import { PartyManager } from './components/PartyManager';
import { ProductManager } from './components/ProductManager';
import { RateManager } from './components/RateManager';
import { Billing } from './components/Billing';
import { DataManager } from './components/DataManager';
import { UserManager } from './components/UserManager';
import { MoreMenu } from './components/MoreMenu';
import { InvoiceLogs } from './components/InvoiceLogs';
import { Ranking } from './components/Ranking';
import { Login } from './components/Login';
import { Store } from './services/store';
import { Cloud } from './services/cloud';
import { Party, Product, SpecialRate, Invoice, ViewState, User } from './types';
import { InvoiceTemplate } from './components/InvoiceTemplate';
import { exportInvoicesToCSV } from './services/csv';

// Declare html2pdf for TypeScript
declare global {
  interface Window {
    html2pdf: any;
  }
}

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // State
  const [validUsers, setValidUsers] = useState<User[]>(() => Store.getUsers());
  const [parties, setParties] = useState<Party[]>(() => Store.getParties());
  const [products, setProducts] = useState<Product[]>(() => Store.getProducts());
  const [specialRates, setSpecialRates] = useState<SpecialRate[]>(() => Store.getRates());
  const [invoices, setInvoices] = useState<Invoice[]>(() => Store.getInvoices());

  // UI State
  const [currentView, setCurrentView] = useState<ViewState>('billing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  // Search State for History View
  const [invoiceSearch, setInvoiceSearch] = useState('');

  // Context Menu State
  const [contextMenu, setContextMenu] = useState<{ visible: boolean; x: number; y: number; invoice: Invoice | null }>({
    visible: false,
    x: 0,
    y: 0,
    invoice: null,
  });

  // PDF Download State
  const [pdfInvoice, setPdfInvoice] = useState<Invoice | null>(null);
  const pdfContainerRef = useRef<HTMLDivElement>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Sync Status
  const [cloudUrl, setCloudUrl] = useState(() => Cloud.getScriptUrl());
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');

  const isFirstLoad = useRef(true);
  const hasPendingChanges = useRef(false);
  // This ref tracks if the current state change was caused by a Cloud Pull
  // If true, we skip the next Auto-Push to prevent overwriting the sheet with what we just downloaded
  const isRemoteUpdate = useRef(false);
  const lastPushTime = useRef(0); 

  const loadLocalData = () => {
    setParties(Store.getParties());
    setProducts(Store.getProducts());
    setSpecialRates(Store.getRates());
    setInvoices(Store.getInvoices());
    setValidUsers(Store.getUsers());
  };

  // Close context menu on click elsewhere
  useEffect(() => {
    const handleClick = () => setContextMenu({ ...contextMenu, visible: false });
    window.addEventListener('click', handleClick);
    return () => window.removeEventListener('click', handleClick);
  }, [contextMenu]);

  // Auto-Print Effect when History Preview Opens
  useEffect(() => {
    if (viewInvoice) {
      // Increased delay to 1000ms to ensure QR code image loads before print dialog
      const timer = setTimeout(() => {
        window.print();
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [viewInvoice]);

  // Handle PDF Generation
  useEffect(() => {
    if (pdfInvoice && pdfContainerRef.current && !isGeneratingPdf) {
      setIsGeneratingPdf(true);
      // Wait for render
      setTimeout(() => {
        const element = pdfContainerRef.current;
        if (!element || !window.html2pdf) {
            setIsGeneratingPdf(false);
            setPdfInvoice(null);
            return;
        }

        const opt = {
          margin: 0,
          filename: `Invoice_${pdfInvoice.invoiceNumber}.pdf`,
          image: { type: 'jpeg', quality: 0.98 },
          html2canvas: { scale: 2, useCORS: true },
          jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        window.html2pdf().set(opt).from(element).save().then(() => {
          setIsGeneratingPdf(false);
          setPdfInvoice(null);
        }).catch((err: any) => {
          console.error('PDF Generation Error:', err);
          setIsGeneratingPdf(false);
          setPdfInvoice(null);
        });
      }, 500); // Wait for QR code and layout
    }
  }, [pdfInvoice, isGeneratingPdf]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) {
      setIsAuthenticated(true);
    }
    if (cloudUrl) {
      Cloud.fetchUsers().then(cloudUsers => {
        if (cloudUsers.length > 1) { 
          setValidUsers(cloudUsers);
          Store.saveUsers(cloudUsers);
        }
      });
    }
  }, []);

  // --- AUTO-PUSH (App -> Sheet) ---
  useEffect(() => {
    Store.saveParties(parties);
    Store.saveProducts(products);
    Store.saveRates(specialRates);
    Store.saveUsers(validUsers);

    if (isFirstLoad.current) {
      isFirstLoad.current = false;
      return;
    }

    // SAFETY GUARD: Never push empty data automatically. 
    if (parties.length === 0 && products.length === 0) return;

    // REMOTE UPDATE CHECK:
    // If this change came from the Cloud (Pull), do NOT push it back.
    if (isRemoteUpdate.current) {
       isRemoteUpdate.current = false; // Reset flag
       return; 
    }

    hasPendingChanges.current = true;

    if (cloudUrl) {
      setSyncStatus('syncing');

      const handler = setTimeout(async () => {
         try {
           await Cloud.syncMasterData(parties, products, specialRates, validUsers);
           lastPushTime.current = Date.now();
           setSyncStatus('synced');
           hasPendingChanges.current = false;
           setTimeout(() => setSyncStatus('idle'), 2000);
         } catch (e) {
           console.error("Auto-sync failed", e);
           setSyncStatus('idle');
           hasPendingChanges.current = false; 
         }
      }, 2000); 

      return () => clearTimeout(handler);
    } else {
       hasPendingChanges.current = false;
    }
  }, [parties, products, specialRates, validUsers, cloudUrl]);

  // --- MANUAL FORCE PUSH ---
  const handleForcePush = async () => {
      if (!cloudUrl) return;
      setSyncStatus('syncing');
      try {
          console.log("Force Pushing Data...");
          await Cloud.syncMasterData(parties, products, specialRates, validUsers);
          lastPushTime.current = Date.now();
          setSyncStatus('synced');
          hasPendingChanges.current = false;
          setTimeout(() => setSyncStatus('idle'), 2000);
          alert("Data successfully uploaded to Google Sheet.");
      } catch(e) {
          console.error(e);
          setSyncStatus('idle');
          alert("Upload failed. Check connection.");
      }
  };

  // --- PULL LOGIC (CRITICAL DATA PROTECTION) ---
  const handleCloudPull = useCallback(async () => {
      // Don't pull if user is actively typing (pending changes) or we are already syncing
      if (syncStatus === 'syncing' || syncStatus === 'pulling' || hasPendingChanges.current) return;
      if (Date.now() - lastPushTime.current < 10000) return; 

      if (!cloudUrl) return;

      try {
        setSyncStatus('pulling');

        const [cloudPartiesRaw, cloudProductsRaw, cloudRatesRaw, cloudInvoices, cloudUsers] = await Promise.all([
           Cloud.fetchData('PARTIES'),
           Cloud.fetchData('PRODUCTS'),
           Cloud.fetchData('RATES'),
           Cloud.fetchInvoices(),
           Cloud.fetchUsers()
        ]);

        // 1. Parse Cloud Data (Parties & Products First)
        const cloudParties: Party[] = cloudPartiesRaw.slice(1).map((r: any[]) => ({
          id: String(r[0]).trim() || `PTY-${Math.random().toString(36).substr(2,9)}`, 
          name: r[1], 
          address: r[2], city: r[3], phone: r[4], 
          gstNumber: r[5], aadharNumber: r[6], panNumber: r[7], email: ''
        })).filter((p: Party) => p.name); 

        const cloudProducts: Product[] = cloudProductsRaw.slice(1).map((r: any[]) => ({
          id: String(r[0]).trim() || `PRD-${Math.random().toString(36).substr(2,9)}`, 
          name: r[1], 
          code: r[2], hsn: r[3], gstPercent: Number(r[4]), 
          qtyPerCase: Number(r[5]), standardRate: Number(r[6]), unit: r[7]
        })).filter((p: Product) => p.name); 

        // If local changes happened while fetching, abort update to protect local work
        if (hasPendingChanges.current) {
           setSyncStatus('idle');
           return;
        }

        // 2. DECIDE MASTER: CLOUD IS MASTER
        // Logic: If Cloud has valid data, we accept it. 
        // We do NOT block it if local is bigger. We assume Cloud is the Truth.

        let finalParties = parties;
        let updateParties = false;

        if (cloudParties.length > 0 && JSON.stringify(cloudParties) !== JSON.stringify(parties)) {
             finalParties = cloudParties;
             updateParties = true;
        }

        let finalProducts = products;
        let updateProducts = false;

        if (cloudProducts.length > 0 && JSON.stringify(cloudProducts) !== JSON.stringify(products)) {
             finalProducts = cloudProducts;
             updateProducts = true;
        }

        // 3. PARSE RATES based on FINAL lists
        let finalRates = specialRates;
        let updateRates = false;

        if (cloudRatesRaw.length > 0) {
            let parsedRates: SpecialRate[] = [];
            const header = cloudRatesRaw[0]; 
            const partyColMap: Record<number, string> = {};

            // Map Columns to Party IDs from FINAL PARTIES list
            for(let i=3; i<header.length; i++) {
                const pName = header[i];
                const pObj = finalParties.find(p => p.name.trim().toLowerCase() === String(pName).trim().toLowerCase());
                if(pObj) partyColMap[i] = pObj.id;
            }

            for(let i=1; i<cloudRatesRaw.length; i++) {
                const row = cloudRatesRaw[i];
                const prodId = String(row[0]).trim();
                // Match against FINAL PRODUCTS list
                const matchedProduct = finalProducts.find(p => p.id === prodId) || finalProducts.find(p => p.name === row[1]);

                if(matchedProduct) {
                    Object.entries(partyColMap).forEach(([colIdx, partyId]) => {
                        const val = parseFloat(row[Number(colIdx)]);
                        if(!isNaN(val) && val > 0) {
                            parsedRates.push({ partyId, productId: matchedProduct.id, rate: val });
                        }
                    });
                }
            }

            if (parsedRates.length > 0 && JSON.stringify(parsedRates) !== JSON.stringify(specialRates)) {
                finalRates = parsedRates;
                updateRates = true;
            }
        }

        // 4. APPLY UPDATES
        // We set the flag IS_REMOTE_UPDATE to true to block the Auto-Push effect
        if (updateParties || updateProducts || updateRates) {
           isRemoteUpdate.current = true;
           if (updateParties) setParties(finalParties);
           if (updateProducts) setProducts(finalProducts);
           if (updateRates) setSpecialRates(finalRates);
        }

        if (cloudInvoices.length !== invoices.length) {
             setInvoices(cloudInvoices);
             Store.saveInvoices(cloudInvoices);
        }

        if (cloudUsers.length > 0 && JSON.stringify(cloudUsers) !== JSON.stringify(validUsers)) {
            setValidUsers(cloudUsers);
            Store.saveUsers(cloudUsers);
        }

        setSyncStatus('idle');

      } catch (e) {
        console.error("Cloud Pull Error", e);
        setSyncStatus('idle');
      }
  }, [parties, products, specialRates, invoices, validUsers, syncStatus, cloudUrl]);

  useEffect(() => {
    if (!cloudUrl) return;
    const interval = setInterval(handleCloudPull, 10000); 
    return () => clearInterval(interval);
  }, [handleCloudPull, cloudUrl]);

  const refreshInvoices = () => {
    setInvoices(Store.getInvoices());
  };

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setCurrentView('billing');
  };

  const handleDownloadSingleInvoice = (invoice: Invoice) => {
    const csv = exportInvoicesToCSV([invoice]);
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI("data:text/csv;charset=utf-8," + csv));
    link.setAttribute("download", `Invoice_${invoice.invoiceNumber}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrintOptions = (e: React.MouseEvent, invoice: Invoice) => {
    e.preventDefault();
    e.stopPropagation();
    setContextMenu({
      visible: true,
      x: e.pageX - 120, // Offset to appear nicely under/near cursor
      y: e.pageY,
      invoice: invoice
    });
  };

  const handleMenuAction = (action: 'print' | 'download') => {
    const inv = contextMenu.invoice;
    setContextMenu({ ...contextMenu, visible: false });

    if (inv) {
      if (action === 'print') {
        setViewInvoice(inv);
      } else if (action === 'download') {
        setPdfInvoice(inv);
      }
    }
  };

  const handleLogin = (user: User) => {
    setIsAuthenticated(true);
    sessionStorage.setItem('gfb_user', JSON.stringify(user));
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('gfb_user');
  };

  // Filter Logic for Invoice History
  const filteredInvoices = invoices.filter(inv => {
    const term = invoiceSearch.toLowerCase();
    return (
      inv.invoiceNumber.toLowerCase().includes(term) ||
      inv.partyName.toLowerCase().includes(term) ||
      (inv.vehicleNumber && inv.vehicleNumber.toLowerCase().includes(term))
    );
  });

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} validUsers={validUsers} />;
  }

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState; icon: any; label: string }) => (
    <button
      onClick={() => {
        setCurrentView(view);
        setEditingInvoice(null); // Clear editing state when changing views
        setIsMobileMenuOpen(false);
      }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium mb-1 ${
        currentView === view 
          ? 'bg-sky-100 text-sky-800 shadow-sm ring-1 ring-sky-200' 
          : 'text-slate-500 hover:bg-slate-50 hover:text-sky-600'
      }`}
    >
      <Icon size={18} strokeWidth={2} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">

      {/* Context Menu (Dropdown) */}
      {contextMenu.visible && (
        <div 
          className="fixed z-[999] bg-white border border-slate-200 shadow-xl rounded-lg py-1 w-40 animate-in fade-in zoom-in-95 duration-100 origin-top-left"
          style={{ top: contextMenu.y, left: Math.min(contextMenu.x, window.innerWidth - 170) }}
        >
          <button 
            onClick={() => handleMenuAction('print')}
            className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-sky-50 hover:text-sky-700 flex items-center gap-2"
          >
            <Printer size={14} /> Print
          </button>
          <button 
            onClick={() => handleMenuAction('download')}
            className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-sky-50 hover:text-sky-700 flex items-center gap-2"
          >
            <FileDown size={14} /> Download PDF
          </button>
        </div>
      )}

      {/* Hidden Container for PDF Generation */}
      {pdfInvoice && (
        <div className="fixed top-0 left-0 z-[-1] w-[210mm] opacity-0 pointer-events-none">
          <div ref={pdfContainerRef}>
            <InvoiceTemplate invoice={pdfInvoice} parties={parties} />
          </div>
        </div>
      )}

      {/* --- FLOATING SYNC STATUS WIDGET --- */}
      {cloudUrl && (
        <div className="fixed bottom-6 right-6 z-50 animate-in slide-in-from-bottom-5">
          <div className="bg-white rounded-xl shadow-lg border border-slate-100 p-3 pr-4 flex items-center gap-3 min-w-[180px]">
            {syncStatus === 'syncing' || syncStatus === 'pulling' ? (
              <RefreshCw className="text-orange-500 animate-spin" size={20} />
            ) : (
              <CheckCircle className="text-emerald-500" size={20} />
            )}

            <div className="flex-1">
              <div className={`font-bold text-xs ${syncStatus === 'syncing' || syncStatus === 'pulling' ? 'text-orange-600' : 'text-slate-700'}`}>
                {syncStatus === 'syncing' ? 'Syncing...' : 
                 syncStatus === 'pulling' ? 'Updating...' :
                 syncStatus === 'synced' ? 'All Saved' : 'Online'}
              </div>
            </div>

            <button 
              onClick={handleCloudPull} 
              className="p-1.5 hover:bg-slate-50 rounded-full text-slate-400 transition-colors"
              title="Force Refresh"
            >
              <RefreshCw size={14} className={syncStatus === 'pulling' ? 'animate-spin' : ''} />
            </button>
          </div>
        </div>
      )}

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 w-full bg-white z-50 border-b border-slate-200 px-4 py-3 flex justify-between items-center shadow-sm no-print">
        <div className="font-bold text-sky-700 text-lg flex items-center gap-2">
            <LayoutDashboard size={20} /> GREENZAR
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
            {isMobileMenuOpen ? <X /> : <Menu />}
          </button>
        </div>
      </div>

      {/* Sidebar Navigation */}
      <div className={`
        fixed md:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 z-40 shadow-xl md:shadow-none no-print
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0
      `}>
        <div className="p-6">
          <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2 tracking-tight">
            <div className="w-8 h-8 bg-sky-600 rounded-lg flex items-center justify-center text-white text-lg font-bold shadow-lg shadow-sky-200">G</div>
            GREENZAR
          </h1>
          <p className="text-[10px] text-slate-400 mt-2 uppercase tracking-wider font-bold pl-10">Food & Beverage</p>
        </div>

        <nav className="px-4 py-2">
          <NavItem view="billing" icon={FileText} label="Create Invoice" />
          <NavItem view="history" icon={History} label="History" />
          <NavItem view="ranking" icon={Trophy} label="Ranking" />
          <NavItem view="logs" icon={ClipboardList} label="All Logs" />

          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Database</div>

          <NavItem view="parties" icon={Users} label="Parties" />
          <NavItem view="products" icon={Package} label="Products" />
          <NavItem view="rates" icon={DollarSign} label="Price Lists" />

          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Configuration</div>
          <NavItem view="users" icon={UserIcon} label="Users" />
          <NavItem view="data" icon={Database} label="Data & Sync" />
          <NavItem view="more" icon={MoreHorizontal} label="More" />
        </nav>

        {/* Simplified Sidebar Footer */}
        <div className="absolute bottom-0 left-0 w-full p-4 border-t border-slate-100 bg-slate-50/50 backdrop-blur-sm">
           <button 
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2 text-xs font-bold text-slate-500 hover:text-red-600 hover:bg-red-50 p-2 rounded-lg transition-colors"
           >
             <LogOut size={14} /> Logout
           </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col h-full overflow-hidden pt-14 md:pt-0 bg-slate-50/50">

        {currentView === 'billing' && (
          <Billing 
            parties={parties} 
            setParties={setParties}
            products={products} 
            specialRates={specialRates}
            onInvoiceSaved={() => {
              refreshInvoices();
              setEditingInvoice(null); // Clear editing state after save
            }}
            initialData={editingInvoice} // Pass data for editing
          />
        )}

        {currentView === 'parties' && (
          <div className="h-full overflow-y-auto">
            <PartyManager parties={parties} setParties={setParties} />
          </div>
        )}

        {currentView === 'products' && (
          <div className="h-full overflow-y-auto">
            <ProductManager products={products} setProducts={setProducts} />
          </div>
        )}

        {currentView === 'rates' && (
          <RateManager 
            parties={parties} 
            products={products} 
            specialRates={specialRates} 
            setSpecialRates={setSpecialRates} 
          />
        )}

        {currentView === 'users' && (
          <div className="h-full overflow-y-auto">
             <UserManager users={validUsers} setUsers={setValidUsers} />
          </div>
        )}

        {currentView === 'more' && (
          <div className="h-full overflow-y-auto">
             <MoreMenu invoices={invoices} parties={parties} products={products} />
          </div>
        )}

        {currentView === 'logs' && (
          <div className="h-full overflow-y-auto">
             <InvoiceLogs invoices={invoices} />
          </div>
        )}

        {currentView === 'ranking' && (
          <div className="h-full overflow-y-auto">
             <Ranking invoices={invoices} parties={parties} />
          </div>
        )}

        {currentView === 'history' && (
          <div className="h-full overflow-y-auto p-4 md:p-8">
             {/* Print Invoice Modal */}
             {viewInvoice && (
              <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-md flex flex-col">
                <div className="flex justify-between items-center p-4 text-white no-print">
                    <h2 className="text-lg font-bold">Print Invoice #{viewInvoice.invoiceNumber}</h2>
                    <div className="flex gap-3">
                      <button 
                        onClick={() => window.print()} 
                        className="bg-white text-slate-900 hover:bg-slate-200 px-4 py-2 rounded-lg font-bold flex items-center gap-2 transition-colors ring-2 ring-white/20"
                      >
                          <Printer size={18} /> Print
                      </button>
                      <button onClick={() => setViewInvoice(null)} className="bg-slate-800 hover:bg-slate-700 text-white px-3 py-2 rounded-lg transition-colors">
                          <X size={20} />
                      </button>
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 md:p-8 flex justify-center bg-slate-800">
                    <div className="print-only-container shadow-2xl scale-100 origin-top bg-white">
                      <InvoiceTemplate invoice={viewInvoice} parties={parties} />
                    </div>
                </div>
                <style>{`
                  @media print {
                    body * { visibility: hidden; }
                    .print-only-container, .print-only-container * { visibility: visible; }
                    .print-only-container { position: absolute; left: 0; top: 0; width: 100%; height: 100%; margin: 0; padding: 0; box-shadow: none; }
                    @page { size: A4; margin: 0; }
                  }
                `}</style>
              </div>
            )}

             {/* Generating PDF Loader */}
             {isGeneratingPdf && (
               <div className="fixed inset-0 z-[200] bg-black/60 flex items-center justify-center backdrop-blur-sm">
                  <div className="bg-white p-6 rounded-2xl flex flex-col items-center">
                     <Loader2 size={40} className="text-sky-600 animate-spin mb-4" />
                     <p className="font-bold text-slate-700">Generating PDF...</p>
                  </div>
               </div>
             )}

             <div className="max-w-6xl mx-auto print:max-w-none print:w-full">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 no-print">
                  <div>
                    <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Invoice History</h2>
                    <p className="text-slate-500 text-sm">View past transactions</p>
                  </div>

                  <div className="flex flex-col md:flex-row gap-3 w-full md:w-auto">
                    {/* Search Bar */}
                    <div className="relative w-full md:w-64">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input 
                          type="text" 
                          placeholder="Search invoices..." 
                          value={invoiceSearch}
                          onChange={(e) => setInvoiceSearch(e.target.value)}
                          className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none bg-white text-slate-900 shadow-sm"
                        />
                        {invoiceSearch && (
                          <button 
                            onClick={() => setInvoiceSearch('')}
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                          >
                            <X size={14} />
                          </button>
                        )}
                    </div>

                    <div className="flex gap-2">
                      <button onClick={() => window.print()} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 rounded-lg shadow-sm hover:bg-slate-50">
                        <Printer size={16} />
                        Print List
                      </button>
                      <button onClick={handleCloudPull} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-sky-700 bg-white border border-slate-200 rounded-lg shadow-sm hover:bg-slate-50">
                        <RefreshCw size={16} className={syncStatus === 'pulling' ? 'animate-spin' : ''} />
                        Refresh
                      </button>
                    </div>
                  </div>
                </div>

                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden ring-1 ring-slate-100 print:ring-0 print:border-none print:shadow-none overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/80 border-b border-slate-200 print:bg-white print:border-slate-900">
                      <tr>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider whitespace-nowrap">Invoice #</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider whitespace-nowrap">Date</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider whitespace-nowrap">Party</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider whitespace-nowrap">Vehicle</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider whitespace-nowrap text-center">Qty</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider whitespace-nowrap text-center">Items</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider whitespace-nowrap text-right">Tax</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider whitespace-nowrap text-right">Disc.</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider text-right whitespace-nowrap">Total</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider text-right whitespace-nowrap no-print">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 print:divide-slate-200">
                      {filteredInvoices.map(inv => (
                        <tr key={inv.id} className="hover:bg-sky-50/50 transition-colors print:hover:bg-transparent">
                          <td className="px-4 py-4 font-mono text-xs text-slate-600 font-bold whitespace-nowrap">{inv.invoiceNumber}</td>
                          <td className="px-4 py-4 text-xs text-slate-600 whitespace-nowrap">{inv.date}</td>
                          <td className="px-4 py-4 text-xs font-medium text-slate-800 whitespace-nowrap max-w-[150px] truncate" title={inv.partyName}>{inv.partyName}</td>
                          <td className="px-4 py-4 text-xs text-slate-500 whitespace-nowrap">{inv.vehicleNumber || '-'}</td>
                          <td className="px-4 py-4 text-xs text-slate-500 text-center whitespace-nowrap">{inv.poNumber || '-'}</td>
                          <td className="px-4 py-4 text-xs text-slate-500 text-center whitespace-nowrap">{inv.items.length}</td>
                          <td className="px-4 py-4 text-xs text-slate-500 text-right whitespace-nowrap">₹{inv.taxAmount.toFixed(2)}</td>
                          <td className="px-4 py-4 text-xs text-red-400 text-right whitespace-nowrap">{inv.globalDiscount > 0 ? `₹${inv.globalDiscount}` : '-'}</td>
                          <td className="px-4 py-4 text-right text-sm font-bold text-slate-700 whitespace-nowrap">₹{inv.grandTotal.toFixed(2)}</td>
                          <td className="px-4 py-4 text-right whitespace-nowrap no-print">
                             <div className="flex justify-end gap-1">
                               <button 
                                onClick={() => handleEditInvoice(inv)}
                                className="text-slate-400 hover:text-orange-600 p-2 hover:bg-orange-50 rounded-lg transition-all"
                                title="Edit Invoice"
                               >
                                 <Edit3 size={16} />
                               </button>
                               <button 
                                onClick={(e) => handlePrintOptions(e, inv)}
                                className="text-slate-400 hover:text-sky-600 p-2 hover:bg-sky-50 rounded-lg transition-all"
                                title="Print / Download Options"
                               >
                                 <Printer size={16} />
                               </button>
                               <button 
                                onClick={() => handleDownloadSingleInvoice(inv)}
                                className="text-slate-400 hover:text-emerald-600 p-2 hover:bg-emerald-50 rounded-lg transition-all"
                                title="Download CSV"
                               >
                                 <Download size={16} />
                               </button>
                             </div>
                          </td>
                        </tr>
                      ))}
                      {filteredInvoices.length === 0 && (
                        <tr>
                          <td colSpan={10} className="px-6 py-12 text-center text-slate-400">
                             {invoiceSearch ? 'No invoices match your search.' : 'No invoices generated yet.'}
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
             </div>
          </div>
        )}

        {currentView === 'data' && (
          <div className="h-full overflow-y-auto">
            <DataManager 
              parties={parties}
              products={products}
              specialRates={specialRates}
              invoices={invoices}
              refreshData={loadLocalData}
              onUrlChange={setCloudUrl}
              onForcePush={handleForcePush} // Connect to parent handler
            />
          </div>
        )}

      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';
import { exportInvoicesToCSV } from '../services/csv';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; // Added for Edit Mode
}

// Defined Vehicle Options
const VEHICLE_OPTIONS = [
  "WB894170", 
  "WB25K1322", 
  "WB25K2982", 
  "WB25L6365", 
  "WB25K1326", 
  "WB25K1341", 
  "WB47J7275", 
  "WB35H3960"
];

// Helper for Local Date (YYYY-MM-DD)
const getTodayString = () => {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);

  // Fix: Use local date function instead of toISOString() which is UTC
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());

  const [customInvoiceNo, setCustomInvoiceNo] = useState(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);

  const [refNo, setRefNo] = useState(''); // This is Total Qty

  // Global Discount State
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);

  // Cloud State
  const [isSaving, setIsSaving] = useState(false);
  const [hasCloudConfig, setHasCloudConfig] = useState(false);

  // Modal States
  const [isPartyModalOpen, setIsPartyModalOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);

  // Quick Party State
  const [newPartyName, setNewPartyName] = useState('');

  // Auto-Print Effect when Preview Opens
  useEffect(() => {
    if (isPreviewOpen && lastInvoice) {
      // Reduced delay to 50ms for near-instant print dialog
      const timer = setTimeout(() => {
        window.print();
      }, 50); 
      return () => clearTimeout(timer);
    }
  }, [isPreviewOpen, lastInvoice]);

  useEffect(() => {
    setHasCloudConfig(!!Cloud.getScriptUrl());
  }, []);

  // --- EDIT MODE INITIALIZATION ---
  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      // Sanitize items to remove NaNs and try to link IDs
      const cleanItems = initialData.items.map(item => {
        // Try to recover productId if missing (common from Cloud fetch)
        let pId = item.productId;
        if (!pId && products.length > 0) {
            // Fuzzy match name
            const found = products.find(p => p.name.trim().toLowerCase() === item.productName.trim().toLowerCase());
            if (found) pId = found.id;
        }

        return {
          ...item,
          productId: pId || '',
          quantity: isNaN(item.quantity) ? 0 : item.quantity,
          rate: isNaN(item.rate) ? 0 : item.rate,
          total: isNaN(item.total) ? 0 : item.total,
          gstPercent: isNaN(item.gstPercent || 0) ? 0 : item.gstPercent
        };
      });

      setItems(cleanItems);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setRefNo(initialData.poNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    } else {
      // Reset if no initial data (switching back to new invoice)
      setSelectedPartyId('');
      setItems([]);
      setInvoiceDate(getTodayString());
      setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
      setVehicleNo('');
      setRefNo('');
      setGlobalDiscount(0);
    }
  }, [initialData, products]); // Re-run if products load later

  // --- AUTO-CALCULATE TOTAL QTY ---
  useEffect(() => {
    const totalQty = items.reduce((sum, item) => sum + item.quantity, 0);
    if (totalQty > 0) {
      setRefNo(totalQty.toString());
    } else {
      setRefNo('');
    }
  }, [items]);

  // --- MANUAL ENTRY STATE ---

  // Vehicle State (Custom Combobox)
  const [vehicleNo, setVehicleNo] = useState('');
  const [showVehicleSuggestions, setShowVehicleSuggestions] = useState(false);
  const [vehicleHighlightIndex, setVehicleHighlightIndex] = useState(0);

  // Product State (Custom Combobox)
  const [currentProductId, setCurrentProductId] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [productHighlightIndex, setProductHighlightIndex] = useState(0);

  // CHANGED: Default Quantity is now 0
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0); 
  const [overrideRate, setOverrideRate] = useState(false); 

  // Refs for Focus Management
  const invoiceNoInputRef = useRef<HTMLInputElement>(null);
  const vehicleInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);
  const addBtnRef = useRef<HTMLButtonElement>(null);

  // --- FILTERING LOGIC ---
  const filteredVehicles = VEHICLE_OPTIONS.filter(v => 
    v.toLowerCase().includes(vehicleNo.toLowerCase())
  );

  const filteredProducts = products.filter(p => {
    const terms = productSearch.toLowerCase().split(' ').filter(t => t);
    const pName = p.name.toLowerCase();
    return terms.every(term => pName.includes(term));
  });

  // --- AUTOMATED PRICING LOGIC ---
  const getRateForProduct = (prodId: string, partyId: string): number => {
    const product = products.find(p => p.id === prodId);
    if (!product) return 0;
    let rateToUse = product.standardRate;
    if (partyId) {
      const special = specialRates.find(r => r.partyId === partyId && r.productId === prodId);
      if (special) rateToUse = special.rate;
    }
    return rateToUse;
  };

  useEffect(() => {
    if (!currentProductId || overrideRate) return;
    setCurrentRate(getRateForProduct(currentProductId, selectedPartyId));
  }, [currentProductId, selectedPartyId, products, specialRates]);

  useEffect(() => {
    setOverrideRate(false);
  }, [currentProductId]);

  // --- KEYBOARD HANDLERS ---

  // 1. Global Shortcuts (Insert Key)
  useEffect(() => {
    const handleGlobalKeys = (e: KeyboardEvent) => {
      if (e.key === 'Insert') {
        e.preventDefault();
        if (isPreviewOpen) {
          handlePrint();
        } else {
          handleSaveInvoice();
        }
      }
      // Print Shortcut in Modal
      if (isPreviewOpen && (e.ctrlKey || e.metaKey) && e.key === 'p') {
        e.preventDefault();
        window.print();
      }
    };
    window.addEventListener('keydown', handleGlobalKeys);
    return () => window.removeEventListener('keydown', handleGlobalKeys);
  }, [isPreviewOpen, items, selectedPartyId]); 

  // 2. Generic Input Navigation
  const handleGenericKeyDown = (e: React.KeyboardEvent, nextRef: React.RefObject<HTMLElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      nextRef.current?.focus();
    }
  };

  // 3. Vehicle Custom Input Handler
  const handleVehicleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.min(prev + 1, filteredVehicles.length - 1));
      setShowVehicleSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showVehicleSuggestions && filteredVehicles.length > 0) {
        setVehicleNo(filteredVehicles[vehicleHighlightIndex]);
      }
      setShowVehicleSuggestions(false);
      productInputRef.current?.focus();
    } else if (e.key === 'Escape') {
      setShowVehicleSuggestions(false);
    }
  };

  // 4. Product Custom Input Handler
  const handleProductKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.min(prev + 1, filteredProducts.length - 1));
      setShowProductSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showProductSuggestions && filteredProducts.length > 0) {
        selectProduct(filteredProducts[productHighlightIndex]);
      } else {
         if (currentProductId) qtyInputRef.current?.focus();
      }
    } else if (e.key === 'Escape') {
      setShowProductSuggestions(false);
    }
  };

  // 5. Quantity Input Handler
  const handleQtyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
       e.preventDefault();
       addItem(e); 
    }
  };

  // --- SELECTION LOGIC ---

  const selectProduct = (p: Product) => {
    setProductSearch(p.name);
    setCurrentProductId(p.id);
    setShowProductSuggestions(false);
    setTimeout(() => qtyInputRef.current?.focus(), 50);
  };

  const handleProductSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setProductSearch(e.target.value);
    setCurrentProductId(''); 
    setProductHighlightIndex(0);
    setShowProductSuggestions(true);
  };

  const handleCreateParty = (e: React.FormEvent) => {
    e.preventDefault();
    if(!newPartyName.trim()) return;
    const newParty: Party = {
      id: crypto.randomUUID(),
      name: newPartyName.trim(),
      phone: '', address: '', city: '', gstNumber: '', aadharNumber: '', panNumber: ''
    };
    setParties([...parties, newParty]); 
    setSelectedPartyId(newParty.id); 
    setNewPartyName('');
    setIsPartyModalOpen(false);
  };

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    // REVERSE GST CALCULATION
    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));
    const grossTotal = currentQty * inclusiveRate; 

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,  
      total: grossTotal,   
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);

    // Reset inputs
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0); // Set back to 0
    setCurrentRate(0);
    productInputRef.current?.focus();
  };

  const removeItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;

    setIsSaving(true);

    const party = parties.find(p => p.id === selectedPartyId);

    // Calculate Totals
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);

    // Reverse calc for Tax Breakdown (Approximation for Display)
    const taxAmount = items.reduce((sum, item) => {
       const taxable = item.total / (1 + (item.gstPercent || 0)/100);
       return sum + (item.total - taxable);
    }, 0);

    const grandTotal = Math.round(subTotal - globalDiscount);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(), // Keep ID if editing
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown Party',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: taxAmount,
      globalDiscount: globalDiscount,
      grandTotal: grandTotal,
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      // Snapshots
      partyAddress: party?.address || '',
      partyGst: party?.gstNumber || '',
      partyPan: party?.panNumber || '',
      partyAadhar: party?.aadharNumber || ''
    };

    try {
        if (initialData) {
            Store.updateInvoice(newInvoice);
        } else {
            Store.saveInvoice(newInvoice);
        }

        if (hasCloudConfig) {
             await Cloud.syncInvoice(newInvoice); 
        }

        setLastInvoice(newInvoice);
        setIsPreviewOpen(true); // Open Preview immediately
        onInvoiceSaved(); // Notify parent (refresh lists)

        // Reset Form ONLY if not editing (or after successful edit, effectively same)
        setItems([]);
        setSelectedPartyId('');
        setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
        setVehicleNo('');
        setRefNo('');
        setGlobalDiscount(0);

    } catch (error) {
        console.error("Save failed", error);
        alert("Saved locally, but cloud sync failed. Check internet.");
    } finally {
        setIsSaving(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="flex h-full flex-col md:flex-row bg-slate-50">

      {/* LEFT: Billing Form */}
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200">
        {/* Header */}
        <div className="px-6 py-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm">
           <div>
             <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
               {initialData ? <Edit3 size={20} className="text-orange-500"/> : <FileText size={20} className="text-sky-600" />} 
               {initialData ? 'Edit Invoice' : 'New Invoice'}
             </h2>
             <div className="text-xs text-slate-400 font-mono mt-0.5">{invoiceDate} • {customInvoiceNo}</div>
           </div>

           <div className="flex items-center gap-2">
              <div className="text-right mr-2 hidden md:block">
                  <div className="text-[10px] text-slate-400 uppercase font-bold">Total Amount</div>
                  <div className="text-xl font-black text-slate-800">
                    ₹{Math.round(items.reduce((sum, item) => sum + item.total, 0) - globalDiscount).toLocaleString('en-IN')}
                  </div>
              </div>
              <button 
                onClick={handleSaveInvoice}
                disabled={isSaving || !selectedPartyId || items.length === 0}
                className="bg-slate-900 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-slate-200 transition-all active:scale-95"
              >
                {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
