                   autoFocus
                   className="w-full border border-slate-300 rounded-lg px-3 py-2 mb-4 focus:ring-2 focus:ring-sky-500 outline-none"
                   value={newPartyName}
                   onChange={e => setNewPartyName(e.target.value)}
                   placeholder="Enter customer name..."
