    <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1" strokeLinecap="round" strokeLinejoin="round" className="opacity-20"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>
);

const CheckCircleIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-emerald-400"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><path d="m9 11 3 3L22 4"/></svg>
);

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';
import { exportInvoicesToCSV } from '../services/csv';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; // Added for Edit Mode
}

// Defined Vehicle Options
const VEHICLE_OPTIONS = [
  "WB894170", 
  "WB25K1322", 
  "WB25K2982", 
  "WB25L6365", 
  "WB25K1326", 
  "WB25K1341", 
  "WB47J7275", 
  "WB35H3960"
];

// Helper for Local Date (YYYY-MM-DD)
const getTodayString = () => {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);

  // Fix: Use local date function instead of toISOString() which is UTC
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());

  const [customInvoiceNo, setCustomInvoiceNo] = useState(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);

  const [refNo, setRefNo] = useState(''); // This is Total Qty

  // Global Discount State
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);

  // Cloud State
  const [isSaving, setIsSaving] = useState(false);
  const [hasCloudConfig, setHasCloudConfig] = useState(false);

  // Modal States
  const [isPartyModalOpen, setIsPartyModalOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);

  // Quick Party State
  const [newPartyName, setNewPartyName] = useState('');

  // Auto-Print Effect when Preview Opens
  useEffect(() => {
    if (isPreviewOpen && lastInvoice) {
      // Reduced delay to 50ms for near-instant print dialog
      const timer = setTimeout(() => {
        window.print();
      }, 50); 
      return () => clearTimeout(timer);
    }
  }, [isPreviewOpen, lastInvoice]);

  useEffect(() => {
    setHasCloudConfig(!!Cloud.getScriptUrl());
  }, []);

  // --- EDIT MODE INITIALIZATION ---
  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      // Sanitize items to remove NaNs and try to link IDs
      const cleanItems = initialData.items.map(item => {
        // Try to recover productId if missing (common from Cloud fetch)
        let pId = item.productId;
        if (!pId && products.length > 0) {
            // Fuzzy match name
            const found = products.find(p => p.name.trim().toLowerCase() === item.productName.trim().toLowerCase());
            if (found) pId = found.id;
        }

        return {
          ...item,
          productId: pId || '',
          quantity: isNaN(item.quantity) ? 0 : item.quantity,
          rate: isNaN(item.rate) ? 0 : item.rate,
          total: isNaN(item.total) ? 0 : item.total,
          gstPercent: isNaN(item.gstPercent || 0) ? 0 : item.gstPercent
        };
      });

      setItems(cleanItems);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setRefNo(initialData.poNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    } else {
      // Reset if no initial data (switching back to new invoice)
      setSelectedPartyId('');
      setItems([]);
      setInvoiceDate(getTodayString());
      setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
      setVehicleNo('');
      setRefNo('');
      setGlobalDiscount(0);
    }
  }, [initialData, products]); // Re-run if products load later

  // --- AUTO-CALCULATE TOTAL QTY ---
  useEffect(() => {
    const totalQty = items.reduce((sum, item) => sum + item.quantity, 0);
    if (totalQty > 0) {
      setRefNo(totalQty.toString());
    } else {
      setRefNo('');
    }
  }, [items]);

  // --- MANUAL ENTRY STATE ---

  // Vehicle State (Custom Combobox)
  const [vehicleNo, setVehicleNo] = useState('');
  const [showVehicleSuggestions, setShowVehicleSuggestions] = useState(false);
  const [vehicleHighlightIndex, setVehicleHighlightIndex] = useState(0);

  // Product State (Custom Combobox)
  const [currentProductId, setCurrentProductId] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [productHighlightIndex, setProductHighlightIndex] = useState(0);

  // CHANGED: Default Quantity is now 0
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0); 
  const [overrideRate, setOverrideRate] = useState(false); 

  // Refs for Focus Management
  const invoiceNoInputRef = useRef<HTMLInputElement>(null);
  const vehicleInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);
  const addBtnRef = useRef<HTMLButtonElement>(null);

  // --- FILTERING LOGIC ---
  const filteredVehicles = VEHICLE_OPTIONS.filter(v => 
    v.toLowerCase().includes(vehicleNo.toLowerCase())
  );

  const filteredProducts = products.filter(p => {
    const terms = productSearch.toLowerCase().split(' ').filter(t => t);
    const pName = p.name.toLowerCase();
    return terms.every(term => pName.includes(term));
  });

  // --- AUTOMATED PRICING LOGIC ---
  const getRateForProduct = (prodId: string, partyId: string): number => {
    const product = products.find(p => p.id === prodId);
    if (!product) return 0;
    let rateToUse = product.standardRate;
    if (partyId) {
      const special = specialRates.find(r => r.partyId === partyId && r.productId === prodId);
      if (special) rateToUse = special.rate;
    }
    return rateToUse;
  };

  useEffect(() => {
    if (!currentProductId || overrideRate) return;
    setCurrentRate(getRateForProduct(currentProductId, selectedPartyId));
  }, [currentProductId, selectedPartyId, products, specialRates]);

  useEffect(() => {
    setOverrideRate(false);
  }, [currentProductId]);

  // --- KEYBOARD HANDLERS ---

  // 1. Global Shortcuts (Insert Key)
  useEffect(() => {
    const handleGlobalKeys = (e: KeyboardEvent) => {
      if (e.key === 'Insert') {
        e.preventDefault();
        if (isPreviewOpen) {
          handlePrint();
        } else {
          handleSaveInvoice();
        }
      }
      // Print Shortcut in Modal
      if (isPreviewOpen && (e.ctrlKey || e.metaKey) && e.key === 'p') {
        e.preventDefault();
        window.print();
      }
    };
    window.addEventListener('keydown', handleGlobalKeys);
    return () => window.removeEventListener('keydown', handleGlobalKeys);
  }, [isPreviewOpen, items, selectedPartyId]); 

  // 2. Generic Input Navigation
  const handleGenericKeyDown = (e: React.KeyboardEvent, nextRef: React.RefObject<HTMLElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      nextRef.current?.focus();
    }
  };

  // 3. Vehicle Custom Input Handler
  const handleVehicleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.min(prev + 1, filteredVehicles.length - 1));
      setShowVehicleSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showVehicleSuggestions && filteredVehicles.length > 0) {
        setVehicleNo(filteredVehicles[vehicleHighlightIndex]);
      }
      setShowVehicleSuggestions(false);
      productInputRef.current?.focus();
    } else if (e.key === 'Escape') {
      setShowVehicleSuggestions(false);
    }
  };

  // 4. Product Custom Input Handler
  const handleProductKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.min(prev + 1, filteredProducts.length - 1));
      setShowProductSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showProductSuggestions && filteredProducts.length > 0) {
        selectProduct(filteredProducts[productHighlightIndex]);
      } else {
         if (currentProductId) qtyInputRef.current?.focus();
      }
    } else if (e.key === 'Escape') {
      setShowProductSuggestions(false);
    }
  };

  // 5. Quantity Input Handler
  const handleQtyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
       e.preventDefault();
       addItem(e); 
    }
  };

  // --- SELECTION LOGIC ---

  const selectProduct = (p: Product) => {
    setProductSearch(p.name);
    setCurrentProductId(p.id);
    setShowProductSuggestions(false);
    setTimeout(() => qtyInputRef.current?.focus(), 50);
  };

  const handleProductSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setProductSearch(e.target.value);
    setCurrentProductId(''); 
    setProductHighlightIndex(0);
    setShowProductSuggestions(true);
  };

  const handleCreateParty = (e: React.FormEvent) => {
    e.preventDefault();
    if(!newPartyName.trim()) return;
    const newParty: Party = {
      id: crypto.randomUUID(),
      name: newPartyName.trim(),
      phone: '', address: '', city: '', gstNumber: '', aadharNumber: '', panNumber: ''
    };
    setParties([...parties, newParty]); 
    setSelectedPartyId(newParty.id); 
    setNewPartyName('');
    setIsPartyModalOpen(false);
  };

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    // REVERSE GST CALCULATION
    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));
    const grossTotal = currentQty * inclusiveRate; 

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,  
      total: grossTotal,   
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);

    // Reset inputs
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0); // Set back to 0
    setCurrentRate(0);
    productInputRef.current?.focus();
  };

  const removeItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;

    setIsSaving(true);

    const party = parties.find(p => p.id === selectedPartyId);

    // Calculate Totals
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);

    // Reverse calc for Tax Breakdown (Approximation for Display)
    const taxAmount = items.reduce((sum, item) => {
       const taxable = item.total / (1 + (item.gstPercent || 0)/100);
       return sum + (item.total - taxable);
    }, 0);

    const grandTotal = Math.round(subTotal - globalDiscount);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(), // Keep ID if editing
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown Party',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: taxAmount,
      globalDiscount: globalDiscount,
      grandTotal: grandTotal,
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      // Snapshots
      partyAddress: party?.address || '',
      partyGst: party?.gstNumber || '',
      partyPan: party?.panNumber || '',
      partyAadhar: party?.aadharNumber || ''
    };

    try {
        if (initialData) {
            Store.updateInvoice(newInvoice);
        } else {
            Store.saveInvoice(newInvoice);
        }

        if (hasCloudConfig) {
             await Cloud.syncInvoice(newInvoice); 
        }

        setLastInvoice(newInvoice);
        setIsPreviewOpen(true); // Open Preview immediately
        onInvoiceSaved(); // Notify parent (refresh lists)

        // Reset Form ONLY if not editing (or after successful edit, effectively same)
        setItems([]);
        setSelectedPartyId('');
        setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
        setVehicleNo('');
        setRefNo('');
        setGlobalDiscount(0);

    } catch (error) {
        console.error("Save failed", error);
        alert("Saved locally, but cloud sync failed. Check internet.");
    } finally {
        setIsSaving(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="flex h-full flex-col md:flex-row bg-slate-50">

      {/* LEFT: Billing Form */}
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200">
        {/* Header */}
        <div className="px-6 py-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm">
           <div>
             <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
               {initialData ? <Edit3 size={20} className="text-orange-500"/> : <FileText size={20} className="text-sky-600" />} 
               {initialData ? 'Edit Invoice' : 'New Invoice'}
             </h2>
             <div className="text-xs text-slate-400 font-mono mt-0.5">{invoiceDate} • {customInvoiceNo}</div>
           </div>

           <div className="flex items-center gap-2">
              <div className="text-right mr-2 hidden md:block">
                  <div className="text-[10px] text-slate-400 uppercase font-bold">Total Amount</div>
                  <div className="text-xl font-black text-slate-800">
                    ₹{Math.round(items.reduce((sum, item) => sum + item.total, 0) - globalDiscount).toLocaleString('en-IN')}
                  </div>
              </div>
              <button 
                onClick={handleSaveInvoice}
                disabled={isSaving || !selectedPartyId || items.length === 0}
                className="bg-slate-900 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-slate-200 transition-all active:scale-95"
              >
                {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
                <span>{initialData ? 'Update' : 'Save'}</span>
              </button>
           </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4 md:space-y-6">

           {/* Row 1: Invoice Details */}
           <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
              <div className="md:col-span-3">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Invoice No</label>
                 <div className="relative">
                    <input 
                      ref={invoiceNoInputRef}
                      type="text" 
                      value={customInvoiceNo}
                      onChange={(e) => setCustomInvoiceNo(e.target.value)}
                      onKeyDown={(e) => handleGenericKeyDown(e, vehicleInputRef)}
                      className="w-full pl-3 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none font-mono text-sm font-bold text-slate-700 bg-white"
                    />
                 </div>
              </div>
              <div className="md:col-span-3">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Date</label>
                 <input 
                    type="date" 
                    value={invoiceDate}
                    onChange={(e) => setInvoiceDate(e.target.value)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none text-sm font-medium text-slate-700 bg-white"
                 />
              </div>
              <div className="md:col-span-3">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Vehicle No</label>
                 <div className="relative">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"><CreditCard size={14} /></div>
                    <input 
                      ref={vehicleInputRef}
                      type="text" 
                      value={vehicleNo}
                      onChange={(e) => {
                         setVehicleNo(e.target.value);
                         setShowVehicleSuggestions(true);
                      }}
                      onFocus={() => setShowVehicleSuggestions(true)}
                      onBlur={() => setTimeout(() => setShowVehicleSuggestions(false), 200)}
                      onKeyDown={handleVehicleKeyDown}
                      placeholder="Vehicle..."
                      className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none text-sm font-medium uppercase bg-white"
                    />
                    {/* Vehicle Suggestions */}
                    {showVehicleSuggestions && filteredVehicles.length > 0 && (
                      <div className="absolute z-20 w-full mt-1 bg-white border border-slate-200 rounded-lg shadow-xl max-h-40 overflow-y-auto">
                        {filteredVehicles.map((v, idx) => (
                          <div 
                            key={v}
                            className={`px-3 py-2 text-sm cursor-pointer hover:bg-sky-50 ${idx === vehicleHighlightIndex ? 'bg-sky-50 text-sky-700 font-bold' : 'text-slate-700'}`}
                            onMouseDown={() => {
                              setVehicleNo(v);
                              productInputRef.current?.focus();
                            }}
                          >
                            {v}
                          </div>
                        ))}
                      </div>
                    )}
                 </div>
              </div>
              <div className="md:col-span-3">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Total Qty (Ref)</label>
                 <div className="relative">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"><Box size={14} /></div>
                    <input 
                      type="text" 
                      value={refNo}
                      onChange={(e) => setRefNo(e.target.value)}
                      placeholder="Auto"
                      readOnly
                      className="w-full pl-9 pr-3 py-2 border border-slate-200 bg-slate-50 text-slate-500 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none text-sm font-medium"
                    />
                 </div>
              </div>
           </div>

           {/* Row 2: Party Selection */}
           <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
              <div className="flex justify-between items-center mb-2">
                 <label className="text-xs font-bold text-slate-500 uppercase flex items-center gap-1"><User size={12} /> Bill To Party</label>
                 <button onClick={() => setIsPartyModalOpen(true)} className="text-[10px] font-bold text-sky-600 hover:underline flex items-center gap-1">
                   <Plus size={10} /> New Party
                 </button>
              </div>
              <select 
                value={selectedPartyId} 
                onChange={e => setSelectedPartyId(e.target.value)}
                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none font-medium text-slate-800 text-sm appearance-none"
              >
                <option value="">-- Select Customer --</option>
                {parties.map(p => (
                  <option key={p.id} value={p.id}>{p.name} {p.city ? `(${p.city})` : ''}</option>
                ))}
              </select>
              {selectedPartyId && (
                 <div className="mt-2 text-xs text-slate-500 pl-1">
                    {(() => {
                        const p = parties.find(party => party.id === selectedPartyId);
                        return p ? (
                            <span className="flex gap-3">
                                {p.city && <span>📍 {p.city}</span>}
                                {p.phone && <span>📞 {p.phone}</span>}
                                {p.gstNumber && <span>🏢 {p.gstNumber}</span>}
                            </span>
                        ) : null;
                    })()}
                 </div>
              )}
           </div>

           {/* Row 3: Product Entry (Combobox + Inputs) */}
           <div className="bg-sky-50/50 p-4 rounded-xl border border-sky-100 shadow-inner">
               <label className="block text-[10px] font-bold text-sky-700 uppercase mb-2">Add Items</label>
               <div className="flex flex-col md:flex-row gap-3 items-end">

                   {/* Product Combobox */}
                   <div className="flex-1 w-full relative">
                      <div className="text-[10px] font-bold text-slate-400 mb-1 ml-1">Product Name</div>
                      <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                          <input 
                            ref={productInputRef}
                            type="text" 
                            value={productSearch}
                            onChange={handleProductSearchChange}
                            onFocus={() => setShowProductSuggestions(true)}
                            onBlur={() => setTimeout(() => setShowProductSuggestions(false), 200)}
                            onKeyDown={handleProductKeyDown}
                            placeholder="Type product name..."
                            className="w-full pl-9 pr-3 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none text-sm font-semibold text-slate-900 bg-white shadow-sm"
                          />
                          {/* Suggestions Dropdown */}
                          {showProductSuggestions && filteredProducts.length > 0 && (
                            <div className="absolute z-30 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-2xl max-h-60 overflow-y-auto">
                              {filteredProducts.map((p, idx) => (
                                <div 
                                  key={p.id}
                                  className={`px-4 py-2 text-sm cursor-pointer border-b border-slate-50 last:border-0 hover:bg-sky-50 ${idx === productHighlightIndex ? 'bg-sky-50' : ''}`}
                                  onMouseDown={() => selectProduct(p)}
                                >
                                  <div className="font-bold text-slate-800">{p.name}</div>
                                  <div className="text-xs text-slate-500 flex justify-between mt-0.5">
                                     <span>Code: {p.code}</span>
                                     <span className="font-mono text-sky-600 font-bold">₹{getRateForProduct(p.id, selectedPartyId)}</span>
                                  </div>
                                </div>
                              ))}
                            </div>
                          )}
                      </div>
                   </div>

                   {/* Qty */}
                   <div className="w-20">
                      <div className="text-[10px] font-bold text-slate-400 mb-1 ml-1 text-center">Qty</div>
                      <input 
                         ref={qtyInputRef}
                         type="number" 
                         value={currentQty || ''}
                         onChange={e => setCurrentQty(parseFloat(e.target.value) || 0)}
                         onKeyDown={handleQtyKeyDown}
                         placeholder="0"
                         className="w-full px-2 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none text-sm font-bold text-center text-slate-900 bg-white shadow-sm"
                      />
                   </div>

                   {/* Rate */}
                   <div className="w-24">
                      <div className="text-[10px] font-bold text-slate-400 mb-1 ml-1 text-center">Rate</div>
                      <input 
                         type="number" 
                         value={currentRate}
                         onChange={e => {
                             setCurrentRate(parseFloat(e.target.value) || 0);
                             setOverrideRate(true);
                         }}
                         onKeyDown={(e) => {
                             if(e.key === 'Enter') { e.preventDefault(); addBtnRef.current?.click(); }
                         }}
                         className={`w-full px-2 py-2.5 border rounded-lg focus:ring-2 focus:ring-sky-500 outline-none text-sm font-bold text-center shadow-sm ${overrideRate ? 'border-orange-300 bg-orange-50 text-orange-800' : 'border-slate-300 bg-white text-slate-900'}`}
                      />
                   </div>

                   {/* Add Button */}
                   <button 
                     ref={addBtnRef}
                     onClick={addItem}
                     disabled={!currentProductId || currentQty <= 0}
                     className="bg-sky-600 hover:bg-sky-700 disabled:opacity-50 disabled:bg-slate-300 text-white p-2.5 rounded-lg shadow-sm transition-colors mb-[1px]"
                   >
                     <Plus size={20} />
                   </button>
               </div>
           </div>

           {/* Items Table */}
           <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden min-h-[200px] flex flex-col">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50 border-b border-slate-200 text-xs text-slate-500 uppercase">
                    <th className="px-4 py-3 font-bold">#</th>
                    <th className="px-4 py-3 font-bold w-1/2">Item</th>
                    <th className="px-4 py-3 font-bold text-center">Qty</th>
                    <th className="px-4 py-3 font-bold text-right">Rate</th>
                    <th className="px-4 py-3 font-bold text-right">Total</th>
                    <th className="px-4 py-3 font-bold text-center"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-sm">
                   {items.map((item, index) => (
                     <tr key={item.id} className="hover:bg-slate-50 group transition-colors">
                       <td className="px-4 py-3 text-slate-400 font-mono text-xs">{index + 1}</td>
                       <td className="px-4 py-3">
                         <div className="font-semibold text-slate-800">{item.productName}</div>
                         <div className="text-[10px] text-slate-400 font-mono">
                           GST: {item.gstPercent}% | Base: {item.baseRate.toFixed(2)}
                         </div>
                       </td>
                       <td className="px-4 py-3 text-center font-bold text-slate-700 bg-slate-50/50">{item.quantity}</td>
                       <td className="px-4 py-3 text-right text-slate-600 font-mono">{item.rate.toFixed(2)}</td>
                       <td className="px-4 py-3 text-right font-bold text-slate-800">{item.total.toFixed(2)}</td>
                       <td className="px-4 py-3 text-center">
                          <button onClick={() => removeItem(item.id)} className="text-slate-300 hover:text-red-500 transition-colors">
                             <Trash2 size={16} />
                          </button>
                       </td>
                     </tr>
                   ))}
                   {items.length === 0 && (
                     <tr>
                        <td colSpan={6} className="px-6 py-12 text-center text-slate-300">
                           <div className="flex flex-col items-center gap-2">
                              <ShoppingBagIcon />
                              <span className="text-sm font-medium">Cart is empty</span>
                           </div>
                        </td>
                     </tr>
                   )}
                </tbody>
              </table>

              {/* Footer Totals */}
              <div className="mt-auto bg-slate-50 border-t border-slate-200 p-4">
                 <div className="flex justify-end gap-8 text-sm">
                    <div className="text-right">
                       <div className="text-slate-500 text-xs uppercase font-bold mb-1">Sub Total</div>
                       <div className="font-bold text-slate-800">₹{items.reduce((s, i) => s + i.total, 0).toFixed(2)}</div>
                    </div>
                    <div className="text-right">
                        <div className="text-slate-500 text-xs uppercase font-bold mb-1">Discount (₹)</div>
                        <input 
                            type="number" 
                            value={globalDiscount} 
                            onChange={(e) => setGlobalDiscount(parseFloat(e.target.value) || 0)}
                            className="w-20 text-right font-bold text-red-600 bg-transparent border-b border-red-200 focus:border-red-500 outline-none p-0"
                        />
                    </div>
                    <div className="text-right pl-6 border-l border-slate-200">
                       <div className="text-slate-500 text-xs uppercase font-bold mb-1">Grand Total</div>
                       <div className="font-black text-xl text-slate-900">₹{Math.round(items.reduce((s, i) => s + i.total, 0) - globalDiscount).toFixed(2)}</div>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      </div>

      {/* Modals */}
      {isPartyModalOpen && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm">
           <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm animate-in zoom-in-95 duration-200">
              <h3 className="text-lg font-bold mb-4">Add Quick Party</h3>
              <form onSubmit={handleCreateParty}>
                 <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Party Name</label>
                 <input 
                   autoFocus
                   className="w-full border border-slate-300 rounded-lg px-3 py-2 mb-4 focus:ring-2 focus:ring-sky-500 outline-none"
                   value={newPartyName}
                   onChange={e => setNewPartyName(e.target.value)}
                   placeholder="Enter customer name..."
                 />
                 <div className="flex justify-end gap-2">
                    <button type="button" onClick={() => setIsPartyModalOpen(false)} className="px-4 py-2 text-slate-500 hover:bg-slate-100 rounded-lg font-medium">Cancel</button>
                    <button type="submit" className="px-4 py-2 bg-sky-600 hover:bg-sky-700 text-white rounded-lg font-bold">Create</button>
                 </div>
              </form>
           </div>
        </div>
      )}

      {/* Invoice Preview Modal */}
      {isPreviewOpen && lastInvoice && (
        <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-md flex flex-col animate-in fade-in duration-200">
           <div className="flex justify-between items-center p-4 text-white no-print">
               <div>
                  <h2 className="text-lg font-bold flex items-center gap-2"><CheckCircleIcon /> Invoice Saved!</h2>
                  <p className="text-xs text-slate-400">Ready to print or download.</p>
               </div>
               <div className="flex gap-3">
                  <button 
                     onClick={handlePrint} 
                     className="bg-white text-slate-900 hover:bg-slate-200 px-6 py-2 rounded-lg font-bold flex items-center gap-2 transition-colors ring-2 ring-white/20"
                   >
                      <Printer size={18} /> Print
                   </button>
                   <button onClick={() => setIsPreviewOpen(false)} className="bg-slate-800 hover:bg-slate-700 text-white px-3 py-2 rounded-lg transition-colors">
                      <X size={20} />
                   </button>
               </div>
           </div>

           <div className="flex-1 overflow-y-auto p-4 md:p-8 flex justify-center bg-slate-800/50">
                <div className="print-only-container shadow-2xl scale-100 origin-top bg-white">
                  <InvoiceTemplate invoice={lastInvoice} parties={parties} />
                </div>
           </div>
           <style>{`
              @media print {
                body * { visibility: hidden; }
                .print-only-container, .print-only-container * { visibility: visible; }
                .print-only-container { position: absolute; left: 0; top: 0; width: 100%; height: 100%; margin: 0; padding: 0; box-shadow: none; }
                @page { size: A4; margin: 0; }
              }
           `}</style>
        </div>
      )}

    </div>
  );
};

const ShoppingBagIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1" strokeLinecap="round" strokeLinejoin="round" className="opacity-20"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>
);

const CheckCircleIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-emerald-400"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><path d="m9 11 3 3L22 4"/></svg>
);

import React, { useState, useMemo } from 'react';
import { Invoice, Party } from '../types';
import { Search, Trophy, Calendar, Filter, Download, DollarSign } from 'lucide-react';

interface Props {
  invoices: Invoice[];
  parties: Party[];
}

export const Ranking: React.FC<Props> = ({ invoices, parties }) => {
  // Default to current month
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0];
  const lastDay = today.toISOString().split('T')[0];

  const [startDate, setStartDate] = useState(firstDay);
  const [endDate, setEndDate] = useState(lastDay);

  const topParties = useMemo(() => {
    const agg: Record<string, { partyId: string, partyName: string, total: number, count: number }> = {};

    invoices.forEach(inv => {
      // Robust Date Comparison
      if (inv.date >= startDate && inv.date <= endDate) {
        // Robust Number Parsing
        const totalAmount = Number(inv.grandTotal) || 0;

        if (!agg[inv.partyId]) {
          agg[inv.partyId] = { 
             partyId: inv.partyId, 
             partyName: inv.partyName || 'Unknown', 
             total: 0, 
             count: 0 
          };
        }
        agg[inv.partyId].total += totalAmount;
        agg[inv.partyId].count += 1;
      }
    });

    // Return ALL parties sorted, slice later for view
    return Object.values(agg).sort((a, b) => b.total - a.total);
  }, [invoices, startDate, endDate]);

  const displayedParties = topParties.slice(0, 10); // Show Top 10 in UI
  const totalVolume = topParties.reduce((sum, p) => sum + p.total, 0);

  const handleDownload = () => {
     let csv = "Rank,Party Name,Invoice Count,Total Sales\n";
     // Export ALL parties, not just top 10
     topParties.forEach((p, idx) => {
         csv += `${idx + 1},"${p.partyName}",${p.count},${p.total}\n`;
     });

     const date = new Date().toISOString().split('T')[0];
     const link = document.createElement("a");
     link.setAttribute("href", encodeURI("data:text/csv;charset=utf-8," + csv));
     link.setAttribute("download", `Ranking_Report_${startDate}_to_${endDate}.csv`);
     document.body.appendChild(link);
     link.click();
     document.body.removeChild(link);
  };

  return (
    <div className="p-6 max-w-5xl mx-auto">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Trophy className="text-yellow-500" /> Top 10 Ranking
          </h2>
          <p className="text-slate-500">Highest billing parties for the selected period.</p>
        </div>

        <button 
            onClick={handleDownload}
            disabled={topParties.length === 0}
            className="bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors font-medium shadow-sm"
        >
            <Download size={18} /> Download Full Report
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
        {/* Filters */}
        <div className="md:col-span-2 bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-4 items-center">
            <div className="flex items-center gap-2 text-slate-500 font-bold uppercase text-xs mr-2">
                <Filter size={14} /> Filter Range
            </div>

            <div>
                <label className="block text-[10px] text-slate-400 font-bold uppercase mb-1">From Date</label>
                <input 
                type="date" 
                value={startDate} 
                onChange={e => setStartDate(e.target.value)}
                className="px-3 py-2 border border-slate-300 rounded-lg text-sm font-medium focus:ring-2 focus:ring-sky-500 outline-none"
                />
            </div>

            <div className="self-end pb-2 text-slate-400 font-bold">-</div>

            <div>
                <label className="block text-[10px] text-slate-400 font-bold uppercase mb-1">To Date</label>
                <input 
                type="date" 
                value={endDate} 
                onChange={e => setEndDate(e.target.value)}
                className="px-3 py-2 border border-slate-300 rounded-lg text-sm font-medium focus:ring-2 focus:ring-sky-500 outline-none"
                />
            </div>
        </div>

        {/* Total Summary Card */}
        <div className="bg-sky-50 border border-sky-100 p-4 rounded-xl flex items-center justify-between">
            <div>
                <p className="text-[10px] uppercase font-bold text-sky-600 mb-1">Total Period Volume</p>
                <h3 className="text-xl font-black text-slate-800">₹{totalVolume.toLocaleString('en-IN')}</h3>
            </div>
            <div className="p-3 bg-sky-200 text-sky-700 rounded-lg">
                <DollarSign size={20} />
            </div>
        </div>
      </div>

      {/* Ranking List */}
      <div className="bg-white rounded-xl shadow-lg border border-slate-100 overflow-hidden">
         <div className="grid grid-cols-12 bg-slate-50 border-b border-slate-200 px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">
             <div className="col-span-2 text-center">Rank</div>
             <div className="col-span-6">Party Name</div>
             <div className="col-span-2 text-center">Invoices</div>
             <div className="col-span-2 text-right">Total Sales</div>
         </div>

         <div className="divide-y divide-slate-100">
             {displayedParties.map((party, index) => {
                 let medalColor = "bg-slate-100 text-slate-500";
                 if (index === 0) medalColor = "bg-yellow-100 text-yellow-700 border border-yellow-200";
                 if (index === 1) medalColor = "bg-slate-200 text-slate-600 border border-slate-300";
                 if (index === 2) medalColor = "bg-orange-100 text-orange-700 border border-orange-200";

                 return (
                    <div key={party.partyId} className="grid grid-cols-12 px-6 py-4 items-center hover:bg-slate-50 transition-colors">
                        <div className="col-span-2 flex justify-center">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${medalColor}`}>
                                {index + 1}
                            </div>
                        </div>
                        <div className="col-span-6">
                            <div className="font-bold text-slate-800 text-base">{party.partyName}</div>
                            <div className="text-xs text-slate-400 font-mono">ID: {party.partyId.slice(0,8)}...</div>
                        </div>
                        <div className="col-span-2 text-center text-slate-600 font-medium">
                            {party.count}
                        </div>
                        <div className="col-span-2 text-right font-black text-slate-800 text-lg">
                            ₹{party.total.toLocaleString('en-IN')}
                        </div>
                    </div>
                 );
             })}

             {topParties.length === 0 && (
                 <div className="p-12 text-center text-slate-400 flex flex-col items-center">
                    <Trophy size={48} className="mb-4 opacity-20" />
                    <p>No billing data found for this date range.</p>
                 </div>
             )}
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';
import { exportInvoicesToCSV } from '../services/csv';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; // Added for Edit Mode
}

// Defined Vehicle Options
const VEHICLE_OPTIONS = [
  "WB894170", 
  "WB25K1322", 
  "WB25K2982", 
  "WB25L6365", 
  "WB25K1326", 
  "WB25K1341", 
  "WB47J7275", 
  "WB35H3960"
];

// Helper for Local Date (YYYY-MM-DD)
const getTodayString = () => {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);

  // Fix: Use local date function instead of toISOString() which is UTC
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());

  const [customInvoiceNo, setCustomInvoiceNo] = useState(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);

  const [refNo, setRefNo] = useState(''); // This is Total Qty

  // Global Discount State
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);

  // Cloud State
  const [isSaving, setIsSaving] = useState(false);
  const [hasCloudConfig, setHasCloudConfig] = useState(false);

  // Modal States
  const [isPartyModalOpen, setIsPartyModalOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);

  // Quick Party State
  const [newPartyName, setNewPartyName] = useState('');

  // Auto-Print Effect when Preview Opens
  useEffect(() => {
    if (isPreviewOpen && lastInvoice) {
      // Reduced delay to 50ms for near-instant print dialog
      const timer = setTimeout(() => {
        window.print();
      }, 50); 
      return () => clearTimeout(timer);
    }
  }, [isPreviewOpen, lastInvoice]);

  useEffect(() => {
    setHasCloudConfig(!!Cloud.getScriptUrl());
  }, []);

  // --- EDIT MODE INITIALIZATION ---
  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      // Sanitize items to remove NaNs and try to link IDs
      const cleanItems = initialData.items.map(item => {
        // Try to recover productId if missing (common from Cloud fetch)
        let pId = item.productId;
        if (!pId && products.length > 0) {
            // Fuzzy match name
            const found = products.find(p => p.name.trim().toLowerCase() === item.productName.trim().toLowerCase());
            if (found) pId = found.id;
        }

        return {
          ...item,
          productId: pId || '',
          quantity: isNaN(item.quantity) ? 0 : item.quantity,
          rate: isNaN(item.rate) ? 0 : item.rate,
          total: isNaN(item.total) ? 0 : item.total,
          gstPercent: isNaN(item.gstPercent || 0) ? 0 : item.gstPercent
        };
      });

      setItems(cleanItems);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setRefNo(initialData.poNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    } else {
      // Reset if no initial data (switching back to new invoice)
      setSelectedPartyId('');
      setItems([]);
      setInvoiceDate(getTodayString());
      setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
      setVehicleNo('');
      setRefNo('');
      setGlobalDiscount(0);
    }
  }, [initialData, products]); // Re-run if products load later

  // --- AUTO-CALCULATE TOTAL QTY ---
  useEffect(() => {
    const totalQty = items.reduce((sum, item) => sum + item.quantity, 0);
    if (totalQty > 0) {
      setRefNo(totalQty.toString());
    } else {
      setRefNo('');
    }
  }, [items]);

  // --- MANUAL ENTRY STATE ---

  // Vehicle State (Custom Combobox)
  const [vehicleNo, setVehicleNo] = useState('');
  const [showVehicleSuggestions, setShowVehicleSuggestions] = useState(false);
  const [vehicleHighlightIndex, setVehicleHighlightIndex] = useState(0);

  // Product State (Custom Combobox)
  const [currentProductId, setCurrentProductId] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [productHighlightIndex, setProductHighlightIndex] = useState(0);

  // CHANGED: Default Quantity is now 0
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0); 
  const [overrideRate, setOverrideRate] = useState(false); 

  // Refs for Focus Management
  const invoiceNoInputRef = useRef<HTMLInputElement>(null);
  const vehicleInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);
  const addBtnRef = useRef<HTMLButtonElement>(null);

  // --- FILTERING LOGIC ---
  const filteredVehicles = VEHICLE_OPTIONS.filter(v => 
    v.toLowerCase().includes(vehicleNo.toLowerCase())
  );

  const filteredProducts = products.filter(p => {
    const terms = productSearch.toLowerCase().split(' ').filter(t => t);
    const pName = p.name.toLowerCase();
    return terms.every(term => pName.includes(term));
  });

  // --- AUTOMATED PRICING LOGIC ---
  const getRateForProduct = (prodId: string, partyId: string): number => {
    const product = products.find(p => p.id === prodId);
    if (!product) return 0;
    let rateToUse = product.standardRate;
    if (partyId) {
      const special = specialRates.find(r => r.partyId === partyId && r.productId === prodId);
      if (special) rateToUse = special.rate;
    }
    return rateToUse;
  };

  useEffect(() => {
    if (!currentProductId || overrideRate) return;
    setCurrentRate(getRateForProduct(currentProductId, selectedPartyId));
  }, [currentProductId, selectedPartyId, products, specialRates]);

  useEffect(() => {
    setOverrideRate(false);
  }, [currentProductId]);

  // --- KEYBOARD HANDLERS ---

  // 1. Global Shortcuts (Insert Key)
  useEffect(() => {
    const handleGlobalKeys = (e: KeyboardEvent) => {
      if (e.key === 'Insert') {
        e.preventDefault();
        if (isPreviewOpen) {
          handlePrint();
        } else {
          handleSaveInvoice();
        }
      }
      // Print Shortcut in Modal
      if (isPreviewOpen && (e.ctrlKey || e.metaKey) && e.key === 'p') {
        e.preventDefault();
        window.print();
      }
    };
    window.addEventListener('keydown', handleGlobalKeys);
    return () => window.removeEventListener('keydown', handleGlobalKeys);
  }, [isPreviewOpen, items, selectedPartyId]); 

  // 2. Generic Input Navigation
  const handleGenericKeyDown = (e: React.KeyboardEvent, nextRef: React.RefObject<HTMLElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      nextRef.current?.focus();
    }
  };

  // 3. Vehicle Custom Input Handler
  const handleVehicleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.min(prev + 1, filteredVehicles.length - 1));
      setShowVehicleSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showVehicleSuggestions && filteredVehicles.length > 0) {
        setVehicleNo(filteredVehicles[vehicleHighlightIndex]);
      }
      setShowVehicleSuggestions(false);
      productInputRef.current?.focus();
    } else if (e.key === 'Escape') {
      setShowVehicleSuggestions(false);
    }
  };

  // 4. Product Custom Input Handler
  const handleProductKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.min(prev + 1, filteredProducts.length - 1));
      setShowProductSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showProductSuggestions && filteredProducts.length > 0) {
        selectProduct(filteredProducts[productHighlightIndex]);
      } else {
         if (currentProductId) qtyInputRef.current?.focus();
      }
    } else if (e.key === 'Escape') {
      setShowProductSuggestions(false);
    }
  };

  // 5. Quantity Input Handler
  const handleQtyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
       e.preventDefault();
       addItem(e); 
    }
  };

  // --- SELECTION LOGIC ---

  const selectProduct = (p: Product) => {
    setProductSearch(p.name);
    setCurrentProductId(p.id);
    setShowProductSuggestions(false);
    setTimeout(() => qtyInputRef.current?.focus(), 50);
  };

  const handleProductSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setProductSearch(e.target.value);
    setCurrentProductId(''); 
    setProductHighlightIndex(0);
    setShowProductSuggestions(true);
  };

  const handleCreateParty = (e: React.FormEvent) => {
    e.preventDefault();
    if(!newPartyName.trim()) return;
    const newParty: Party = {
      id: crypto.randomUUID(),
      name: newPartyName.trim(),
      phone: '', address: '', city: '', gstNumber: '', aadharNumber: '', panNumber: ''
    };
    setParties([...parties, newParty]); 
    setSelectedPartyId(newParty.id); 
    setNewPartyName('');
    setIsPartyModalOpen(false);
  };

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    // REVERSE GST CALCULATION
    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));
    const grossTotal = currentQty * inclusiveRate; 

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,  
      total: grossTotal,   
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);

    // Reset inputs
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0); // Set back to 0
    setCurrentRate(0);
    productInputRef.current?.focus();
  };

  const removeItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;

    setIsSaving(true);

    const party = parties.find(p => p.id === selectedPartyId);

    // Calculate Totals
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);

    // Reverse calc for Tax Breakdown (Approximation for Display)
    const taxAmount = items.reduce((sum, item) => {
       const taxable = item.total / (1 + (item.gstPercent || 0)/100);
       return sum + (item.total - taxable);
    }, 0);

    const grandTotal = Math.round(subTotal - globalDiscount);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(), // Keep ID if editing
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown Party',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: taxAmount,
      globalDiscount: globalDiscount,
      grandTotal: grandTotal,
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      // Snapshots
      partyAddress: party?.address || '',
      partyGst: party?.gstNumber || '',
      partyPan: party?.panNumber || '',
      partyAadhar: party?.aadharNumber || ''
    };

    try {
        if (initialData) {
            Store.updateInvoice(newInvoice);
        } else {
            Store.saveInvoice(newInvoice);
        }

        if (hasCloudConfig) {
             await Cloud.syncInvoice(newInvoice); 
        }

        setLastInvoice(newInvoice);
        setIsPreviewOpen(true); // Open Preview immediately
        onInvoiceSaved(); // Notify parent (refresh lists)

        // Reset Form ONLY if not editing (or after successful edit, effectively same)
        setItems([]);
        setSelectedPartyId('');
        setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
        setVehicleNo('');
        setRefNo('');
        setGlobalDiscount(0);

    } catch (error) {
        console.error("Save failed", error);
        alert("Saved locally, but cloud sync failed. Check internet.");
    } finally {
        setIsSaving(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="flex h-full flex-col md:flex-row bg-slate-50">

      {/* LEFT: Billing Form */}
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200">
        {/* Header */}
        <div className="px-6 py-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm">
           <div>
             <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
               {initialData ? <Edit3 size={20} className="text-orange-500"/> : <FileText size={20} className="text-sky-600" />} 
               {initialData ? 'Edit Invoice' : 'New Invoice'}
             </h2>
             <div className="text-xs text-slate-400 font-mono mt-0.5">{invoiceDate} • {customInvoiceNo}</div>
           </div>

           <div className="flex items-center gap-2">
              <div className="text-right mr-2 hidden md:block">
                  <div className="text-[10px] text-slate-400 uppercase font-bold">Total Amount</div>
                  <div className="text-xl font-black text-slate-800">
                    ₹{Math.round(items.reduce((sum, item) => sum + item.total, 0) - globalDiscount).toLocaleString('en-IN')}
                  </div>
              </div>
              <button 
                onClick={handleSaveInvoice}
                disabled={isSaving || !selectedPartyId || items.length === 0}
                className="bg-slate-900 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-slate-200 transition-all active:scale-95"
              >
                {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
                <span>{initialData ? 'Update' : 'Save'}</span>
              </button>
           </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4 md:space-y-6">

           {/* Section 1: Party Selection (Moved to Top) */}
           <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200">
              <div className="flex justify-between items-center mb-2">
                 <label className="text-xs font-bold text-slate-500 uppercase flex items-center gap-1"><User size={12} /> Bill To Party</label>
                 <button onClick={() => setIsPartyModalOpen(true)} className="text-[10px] font-bold text-sky-600 hover:underline flex items-center gap-1">
                   <Plus size={10} /> New Party
                 </button>
              </div>
              <select 
                value={selectedPartyId} 
                onChange={e => setSelectedPartyId(e.target.value)}
                className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none font-medium text-slate-800 text-sm appearance-none"
              >
                <option value="">-- Select Customer --</option>
                {parties.map(p => (
                  <option key={p.id} value={p.id}>{p.name} {p.city ? `(${p.city})` : ''}</option>
                ))}
              </select>
              {selectedPartyId && (
                 <div className="mt-2 text-xs text-slate-500 pl-1">
                    {(() => {
                        const p = parties.find(party => party.id === selectedPartyId);
                        return p ? (
                            <span className="flex gap-3">
                                {p.city && <span>📍 {p.city}</span>}
                                {p.phone && <span>📞 {p.phone}</span>}
                                {p.gstNumber && <span>🏢 {p.gstNumber}</span>}
                            </span>
                        ) : null;
                    })()}
                 </div>
              )}
           </div>

           {/* Section 2: Invoice Details (Moved Below Party) */}
           <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
              <div className="md:col-span-3">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Invoice No</label>
                 <div className="relative">
                    <input 
                      ref={invoiceNoInputRef}
                      type="text" 
                      value={customInvoiceNo}
                      onChange={(e) => setCustomInvoiceNo(e.target.value)}
                      onKeyDown={(e) => handleGenericKeyDown(e, vehicleInputRef)}
