              <div className="md:col-span-3">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Date</label>
                 <input 
                    type="date" 
                    value={invoiceDate}
                    onChange={(e) => setInvoiceDate(e.target.value)}
