const numberToWords = (num: number): string => {
  const a = ['','One ','Two ','Three ','Four ','Five ','Six ','Seven ','Eight ','Nine ','Ten ','Eleven ','Twelve ','Thirteen ','Fourteen ','Fifteen ','Sixteen ','Seventeen ','Eighteen ','Nineteen '];
  const b = ['', '', 'Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];

  const convert = (n: number): string => {
    if (n === 0) return '';
    if (n < 20) return a[n];
    if (n < 100) return b[Math.floor(n / 10)] + (n % 10 !== 0 ? ' ' + a[n % 10] : '');
    if (n < 1000) return a[Math.floor(n / 100)] + 'Hundred ' + convert(n % 100);
    if (n < 100000) return convert(Math.floor(n / 1000)) + 'Thousand ' + convert(n % 1000);
    if (n < 10000000) return convert(Math.floor(n / 100000)) + 'Lakh ' + convert(n % 100000);
    return convert(Math.floor(n / 10000000)) + 'Crore ' + convert(n % 10000000);
  };

  const numInt = Math.floor(num);
  if (numInt === 0) return 'Zero Rupees Only';
  return `Rupees ${convert(numInt)}Only`; 
};

interface Props {
  invoice: Invoice;
  parties: Party[];
}

export const InvoiceTemplate: React.FC<Props> = ({ invoice, parties }) => {
  const party = parties.find(p => p.id === invoice.partyId);

  // Recalculate display totals from items
  let displayTaxable = 0;
  let displayCGST = 0;
  let displaySGST = 0;
  let totalCalculatedQty = 0;

  invoice.items.forEach(item => {
    const rate = item.baseRate || (item.rate / (1 + (item.gstPercent || 0)/100));
    const taxableVal = rate * item.quantity;
    const itemTotal = item.total;
    const taxAmount = itemTotal - taxableVal;

    displayTaxable += taxableVal;
    displayCGST += taxAmount / 2;
    displaySGST += taxAmount / 2;
    totalCalculatedQty += item.quantity;
  });

  const exactTotal = (invoice.subTotal || 0) - (invoice.globalDiscount || 0);
  const roundOff = invoice.grandTotal - exactTotal;

  const displayGst = invoice.partyGst || party?.gstNumber || 'NO';
  const displayPan = invoice.partyPan || party?.panNumber || '-';
  const displayAddress = invoice.partyAddress || party?.address;
  const displayCity = party?.city || '';
  const displayTotalQty = invoice.poNumber ? invoice.poNumber : totalCalculatedQty;
  const partyName = party?.name || invoice.partyName;

  // Format Address lines
  const fullAddress = [displayAddress, displayCity].filter(Boolean).join(', ').toUpperCase();

  return (
      <div className="bg-white text-slate-900 p-8 max-w-[210mm] min-h-[297mm] mx-auto leading-tight font-sans flex flex-col box-border">

        {/* Main Content */}
        <div className="flex-1"> 
            {/* Header */}
