                    <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2">Bill To</h3>
                    <div className="text-sm font-bold text-slate-900 uppercase mb-1">{partyName}</div>

                    {/* Phone Number Moved Here - Full Gray */}
                    <div className="text-[10px] text-slate-500 font-medium mb-1">Ph: {displayPhone}</div>

                    <div className="text-[10px] text-slate-800 uppercase leading-relaxed mb-2 max-w-[250px] font-medium">{fullAddress}</div>

                    <div className="text-[10px] space-y-0.5 text-slate-800">
                        <div className="flex gap-1">
                            <span className="font-bold w-14">GSTIN:</span>
                            <span className="font-mono">{displayGst}</span>
                        </div>
                        <div className="flex gap-1">
                            <span className="font-bold w-14">PAN:</span>
                            <span className="font-mono">{displayPan}</span>
                        </div>
                        <div className="flex gap-1">
                            <span className="font-bold w-14">AADHAR:</span>
                            <span className="font-mono">{displayAadhar}</span>
                        </div>
                    </div>
                </div>

                <div className="w-1/2">
                    <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2">Ship To</h3>
                    <div className="text-sm font-bold text-slate-900 uppercase mb-1">{partyName}</div>

                    {/* Phone Number Moved Here - Full Gray */}
                    <div className="text-[10px] text-slate-500 font-medium mb-1">Ph: {displayPhone}</div>

                    <div className="text-[10px] text-slate-800 uppercase leading-relaxed mb-2 max-w-[250px] font-medium">{fullAddress}</div>
                </div>
            </div>

            {/* Table */}
            <div className="mb-6">
                <table className="w-full text-right border-collapse">
                    <thead>
                        <tr className="bg-slate-100 text-[9px] font-bold uppercase text-slate-600 tracking-wider border-b border-t border-slate-200">
                            <th className="py-2 pl-2 text-left w-8">#</th>
                            <th className="py-2 text-left">Item Description</th>
                            <th className="py-2 text-center">HSN</th>
                            <th className="py-2 text-center">GST</th>
                            <th className="py-2 text-center">Qty</th>
                            <th className="py-2">Rate</th>
                            <th className="py-2">Taxable</th>
                            <th className="py-2">CGST</th>
                            <th className="py-2">SGST</th>
                            <th className="py-2 pr-2">Total</th>
                        </tr>
                    </thead>
                    <tbody className="text-[10px] font-medium text-slate-800">
                    {invoice.items.map((item, idx) => {
                        const gst = item.gstPercent || 0;
                        const rate = item.baseRate || (item.rate / (1 + gst/100));
                        const taxableVal = rate * item.quantity;
                        const taxAmount = item.total - taxableVal;
                        const halfTaxAmount = taxAmount / 2;

                        return (
                        <tr key={idx} className="border-b border-slate-100 hover:bg-slate-50/50">
                            <td className="py-2 pl-2 text-left text-slate-500">{idx + 1}</td>
                            <td className="py-2 text-left font-bold text-slate-900">{item.productName}</td>
                            <td className="py-2 text-center">{item.hsn || '2201'}</td>
                            <td className="py-2 text-center">{gst}%</td>
                            <td className="py-2 text-center font-bold text-slate-900">{item.quantity}</td>
                            <td className="py-2">{rate.toFixed(2)}</td>
                            <td className="py-2">{taxableVal.toFixed(2)}</td>
                            <td className="py-2">{halfTaxAmount.toFixed(2)}</td>
                            <td className="py-2">{halfTaxAmount.toFixed(2)}</td>
                            <td className="py-2 pr-2 font-bold text-slate-900">{item.total.toFixed(2)}</td>
                        </tr>
                        );
                    })}
                    </tbody>
                </table>
            </div>

            {/* Footer Section */}
            <div className="flex gap-8 items-start border-t border-slate-200 pt-6">

                {/* Bank Details & Terms */}
                <div className="w-1/2">
                    <h4 className="text-[9px] font-bold uppercase tracking-wider text-slate-600 mb-2">Bank Details</h4>
                    <div className="bg-slate-50/50 rounded p-3 text-[10px] border border-slate-200 space-y-1 mb-4 text-slate-800">
                        <div className="flex justify-between"><span className="text-slate-600 font-medium">Account Name</span><span className="font-bold">Greenzar Food And Beverage</span></div>
                        <div className="flex justify-between"><span className="text-slate-600 font-medium">Bank Name</span><span className="font-bold">UCO BANK</span></div>
                        <div className="flex justify-between"><span className="text-slate-600 font-medium">Branch</span><span className="font-bold">BADU BR.</span></div>
                        <div className="flex justify-between"><span className="text-slate-600 font-medium">A/C No</span><span className="font-bold font-mono">06710510011188</span></div>
                        <div className="flex justify-between"><span className="text-slate-600 font-medium">IFSC</span><span className="font-bold font-mono">UCBA0000671</span></div>
                    </div>

                    <div className="text-[9px] text-slate-600 space-y-1 leading-relaxed">
                        <p><span className="font-bold text-slate-800">Terms:</span> 1. Goods once sold will not be taken back.</p>
                        <p>2. Interest @ 18% p.a. charged if payment delayed.</p>
                        <p>3. Complete payment within 30 days of the billing date.</p>
                    </div>
                </div>

                {/* Totals */}
                <div className="w-1/2 pl-8">
                    <div className="space-y-2 text-[11px] border-b border-slate-200 pb-3 mb-2">
                        <div className="flex justify-between text-slate-600">
                            <span>Taxable Amount</span>
                            <span className="font-semibold text-slate-900">₹{displayTaxable.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600">
                            <span>Add: CGST</span>
                            <span className="font-semibold text-slate-900">₹{displayCGST.toFixed(2)}</span>
                        </div>
                        <div className="flex justify-between text-slate-600">
                            <span>Add: SGST</span>
                            <span className="font-semibold text-slate-900">₹{displaySGST.toFixed(2)}</span>
                        </div>
                        {invoice.globalDiscount > 0 && (
                            <div className="flex justify-between text-slate-600">
                                <span>Less: Discount</span>
                                <span className="font-medium text-red-600">- {invoice.globalDiscount.toFixed(2)}</span>
                            </div>
                        )}
                        <div className="flex justify-between text-slate-600">
                            <span>Round Off / Adj.</span>
                            <span className="font-medium text-slate-900">{roundOff.toFixed(2)}</span>
                        </div>
                    </div>

                    <div className="flex justify-between items-center py-2 mb-4">
                        <span className="font-bold text-sm text-slate-900 uppercase">Grand Total</span>
                        <span className="font-black text-2xl text-slate-900">₹{invoice.grandTotal.toLocaleString('en-IN')}.00</span>
                    </div>

                    <div className="text-right mb-12">
                        <p className="text-[9px] text-slate-500 font-bold uppercase mb-1">Amount in Words</p>
                        <p className="text-sm font-serif italic text-slate-900 font-medium">{numberToWords(invoice.grandTotal)}</p>
                    </div>

                    <div className="text-center flex flex-col items-end">
                        <p className="text-[9px] font-bold uppercase tracking-wider text-slate-800 mb-1">Authorized Signatory</p>
                        <p className="text-[8px] text-slate-500">For GREENZAR FOOD AND BEVERAGE</p>
                    </div>
                </div>
            </div>
        </div>

        {/* Footer Note */}
        <div className="mt-auto pt-4 text-center border-t border-slate-50">
             <p className="text-[8px] text-slate-900 font-bold">This invoice is generated using GREENZAR F & B BILLING Software.</p>
        </div>

      </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';
import { exportInvoicesToCSV } from '../services/csv';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; // Added for Edit Mode
}

// Defined Vehicle Options
const VEHICLE_OPTIONS = [
  "WB894170", 
  "WB25K1322", 
  "WB25K2982", 
  "WB25L6365", 
  "WB25K1326", 
  "WB25K1341", 
  "WB47J7275", 
  "WB35H3960"
];

// Helper for Local Date (YYYY-MM-DD)
const getTodayString = () => {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);

  // Fix: Use local date function instead of toISOString() which is UTC
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());

  const [customInvoiceNo, setCustomInvoiceNo] = useState(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);

  const [refNo, setRefNo] = useState(''); // This is Total Qty

  // Global Discount State
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);

  // Cloud State
  const [isSaving, setIsSaving] = useState(false);
  const [hasCloudConfig, setHasCloudConfig] = useState(false);

  // Modal States
  const [isPartyModalOpen, setIsPartyModalOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);

  // Quick Party State
  const [newPartyName, setNewPartyName] = useState('');
  const [newPartyPhone, setNewPartyPhone] = useState(''); // Added Phone State

  // Auto-Print Effect when Preview Opens
  useEffect(() => {
    if (isPreviewOpen && lastInvoice) {
      // Increased delay to 1500ms to ensure QR code loads before print dialog
      const timer = setTimeout(() => {
        window.print();
      }, 1500); 
      return () => clearTimeout(timer);
    }
  }, [isPreviewOpen, lastInvoice]);

  useEffect(() => {
    setHasCloudConfig(!!Cloud.getScriptUrl());
  }, []);

  // --- PARTY SEARCH STATE ---
  const [partySearch, setPartySearch] = useState('');
  const [showPartySuggestions, setShowPartySuggestions] = useState(false);
  const [partyHighlightIndex, setPartyHighlightIndex] = useState(0);

  // --- EDIT MODE INITIALIZATION ---
  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);

      // Populate party search text
      const p = parties.find(party => party.id === initialData.partyId);
      if(p) setPartySearch(p.name);
      else setPartySearch(initialData.partyName);

      // Sanitize items to remove NaNs and try to link IDs
      const cleanItems = initialData.items.map(item => {
        // Try to recover productId if missing (common from Cloud fetch)
        let pId = item.productId;
        if (!pId && products.length > 0) {
            // Fuzzy match name
            const found = products.find(p => p.name.trim().toLowerCase() === item.productName.trim().toLowerCase());
            if (found) pId = found.id;
        }

        return {
          ...item,
          productId: pId || '',
          quantity: isNaN(item.quantity) ? 0 : item.quantity,
          rate: isNaN(item.rate) ? 0 : item.rate,
          total: isNaN(item.total) ? 0 : item.total,
          gstPercent: isNaN(item.gstPercent || 0) ? 0 : item.gstPercent
        };
      });

      setItems(cleanItems);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setRefNo(initialData.poNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    } else {
      // Reset if no initial data (switching back to new invoice)
      setSelectedPartyId('');
      setPartySearch('');
      setItems([]);
      setInvoiceDate(getTodayString());
      setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
      setVehicleNo('');
      setRefNo('');
      setGlobalDiscount(0);

      // Auto Focus Party Input on New Load
      setTimeout(() => partyInputRef.current?.focus(), 100);
    }
  }, [initialData, products]); // Re-run if products load later

  // --- AUTO-CALCULATE TOTAL QTY ---
  useEffect(() => {
    const totalQty = items.reduce((sum, item) => sum + item.quantity, 0);
    if (totalQty > 0) {
      setRefNo(totalQty.toString());
    } else {
      setRefNo('');
    }
  }, [items]);

  // --- MANUAL ENTRY STATE ---

  // Vehicle State (Custom Combobox)
  const [vehicleNo, setVehicleNo] = useState('');
  const [showVehicleSuggestions, setShowVehicleSuggestions] = useState(false);
  const [vehicleHighlightIndex, setVehicleHighlightIndex] = useState(0);

  // Product State (Custom Combobox)
  const [currentProductId, setCurrentProductId] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [productHighlightIndex, setProductHighlightIndex] = useState(0);

  // CHANGED: Default Quantity is now 0
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0); 
  const [overrideRate, setOverrideRate] = useState(false); 

  // Refs for Focus Management
  const partyInputRef = useRef<HTMLInputElement>(null);
  const invoiceNoInputRef = useRef<HTMLInputElement>(null);
  const vehicleInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);
  const addBtnRef = useRef<HTMLButtonElement>(null);

  // --- FILTERING LOGIC ---
  const filteredParties = parties.filter(p => p.name.toLowerCase().includes(partySearch.toLowerCase()));

  const filteredVehicles = VEHICLE_OPTIONS.filter(v => 
    v.toLowerCase().includes(vehicleNo.toLowerCase())
  );

  const filteredProducts = products.filter(p => {
    const terms = productSearch.toLowerCase().split(' ').filter(t => t);
    const pName = p.name.toLowerCase();
    return terms.every(term => pName.includes(term));
  });

  // --- AUTOMATED PRICING LOGIC ---
  const getRateForProduct = (prodId: string, partyId: string): number => {
    const product = products.find(p => p.id === prodId);
    if (!product) return 0;
    let rateToUse = product.standardRate;
    if (partyId) {
      const special = specialRates.find(r => r.partyId === partyId && r.productId === prodId);
      if (special) rateToUse = special.rate;
    }
    return rateToUse;
  };

  useEffect(() => {
    if (!currentProductId || overrideRate) return;
    setCurrentRate(getRateForProduct(currentProductId, selectedPartyId));
  }, [currentProductId, selectedPartyId, products, specialRates]);

  useEffect(() => {
    setOverrideRate(false);
  }, [currentProductId]);

  // --- KEYBOARD HANDLERS ---

  // 1. Global Shortcuts (Insert Key)
  useEffect(() => {
    const handleGlobalKeys = (e: KeyboardEvent) => {
      if (e.key === 'Insert') {
        e.preventDefault();
        if (isPreviewOpen) {
          handlePrint();
        } else {
          handleSaveInvoice();
        }
      }
      // Print Shortcut in Modal
      if (isPreviewOpen && (e.ctrlKey || e.metaKey) && e.key === 'p') {
        e.preventDefault();
        window.print();
      }
    };
    window.addEventListener('keydown', handleGlobalKeys);
    return () => window.removeEventListener('keydown', handleGlobalKeys);
  }, [isPreviewOpen, items, selectedPartyId]); 

  // 2. Generic Input Navigation (Invoice No -> Vehicle)
  const handleGenericKeyDown = (e: React.KeyboardEvent, nextRef: React.RefObject<HTMLElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      nextRef.current?.focus();
    }
  };

  // 3. Party Custom Input Handler
  const handlePartyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
        e.preventDefault();
        setPartyHighlightIndex(prev => Math.min(prev + 1, filteredParties.length - 1));
        setShowPartySuggestions(true);
    } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setPartyHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
        e.preventDefault();
        if (showPartySuggestions && filteredParties.length > 0) {
            selectParty(filteredParties[partyHighlightIndex]);
        } else {
            // Even if list closed, if text exact match, select it
            const exactMatch = filteredParties.find(p => p.name.toLowerCase() === partySearch.toLowerCase());
            if (exactMatch) selectParty(exactMatch);
            else invoiceNoInputRef.current?.focus(); // Just move next if typed manually
        }
    } else if (e.key === 'Escape') {
        setShowPartySuggestions(false);
    }
  };

  // 4. Vehicle Custom Input Handler
  const handleVehicleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.min(prev + 1, filteredVehicles.length - 1));
      setShowVehicleSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showVehicleSuggestions && filteredVehicles.length > 0) {
        setVehicleNo(filteredVehicles[vehicleHighlightIndex]);
      }
      setShowVehicleSuggestions(false);
      productInputRef.current?.focus();
    } else if (e.key === 'Escape') {
      setShowVehicleSuggestions(false);
    }
  };

  // 5. Product Custom Input Handler
  const handleProductKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.min(prev + 1, filteredProducts.length - 1));
      setShowProductSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showProductSuggestions && filteredProducts.length > 0) {
        selectProduct(filteredProducts[productHighlightIndex]);
      } else {
         if (currentProductId) qtyInputRef.current?.focus();
      }
    } else if (e.key === 'Escape') {
      setShowProductSuggestions(false);
    }
  };

  // 6. Quantity Input Handler
  const handleQtyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
       e.preventDefault();
       addItem(e); 
    }
  };

  // --- SELECTION LOGIC ---

  const selectParty = (p: Party) => {
      setSelectedPartyId(p.id);
      setPartySearch(p.name);
      setShowPartySuggestions(false);
      invoiceNoInputRef.current?.focus();
  };

  const selectProduct = (p: Product) => {
    setProductSearch(p.name);
    setCurrentProductId(p.id);
    setShowProductSuggestions(false);
    setTimeout(() => qtyInputRef.current?.focus(), 50);
  };

  const handleProductSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setProductSearch(e.target.value);
    setCurrentProductId(''); 
    setProductHighlightIndex(0);
    setShowProductSuggestions(true);
  };

  const handleCreateParty = (e: React.FormEvent) => {
    e.preventDefault();
    if(!newPartyName.trim()) return;
    const newParty: Party = {
      id: crypto.randomUUID(),
      name: newPartyName.trim(),
      phone: newPartyPhone.trim(), // Capture Phone Number
      address: '', city: '', gstNumber: '', aadharNumber: '', panNumber: ''
    };
    setParties([...parties, newParty]); 
    setSelectedPartyId(newParty.id); 
    setPartySearch(newParty.name);

    // Reset and Close
    setNewPartyName('');
    setNewPartyPhone('');
    setIsPartyModalOpen(false);
    invoiceNoInputRef.current?.focus();
  };

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    // REVERSE GST CALCULATION
    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));
    const grossTotal = currentQty * inclusiveRate; 

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,  
      total: grossTotal,   
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);

    // Reset inputs
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0); // Set back to 0
    setCurrentRate(0);
    productInputRef.current?.focus();
  };

  const removeItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;

    // Optimistic UI Update - Show saving state briefly but proceed fast
    setIsSaving(true);

    const party = parties.find(p => p.id === selectedPartyId);

    // Calculate Totals
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);

    // Reverse calc for Tax Breakdown (Approximation for Display)
    const taxAmount = items.reduce((sum, item) => {
       const taxable = item.total / (1 + (item.gstPercent || 0)/100);
       return sum + (item.total - taxable);
    }, 0);

    const grandTotal = Math.round(subTotal - globalDiscount);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(), // Keep ID if editing
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown Party',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: taxAmount,
      globalDiscount: globalDiscount,
      grandTotal: grandTotal,
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      // Snapshots - Combined address to ensure full details are saved
      partyAddress: party ? [party.address, party.city].filter(Boolean).join(', ') : '',
      partyGst: party?.gstNumber || '',
      partyPan: party?.panNumber || '',
      partyAadhar: party?.aadharNumber || '',
      partyPhone: party?.phone || ''
    };

    try {
        // 1. Local Save (Instant)
        if (initialData) {
            Store.updateInvoice(newInvoice);
        } else {
            Store.saveInvoice(newInvoice);
        }

        // 2. Set UI State Immediately
        setLastInvoice(newInvoice);
        setIsPreviewOpen(true); 
        onInvoiceSaved(); 

        // 3. Reset Form
        setItems([]);
        setSelectedPartyId('');
        setPartySearch('');
        setCustomInvoiceNo(`GFB${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`);
        setVehicleNo('');
        setRefNo('');
        setGlobalDiscount(0);
        setTimeout(() => partyInputRef.current?.focus(), 100);

        // 4. Background Sync (Non-blocking)
        if (hasCloudConfig) {
             Cloud.syncInvoice(newInvoice).catch(err => {
                 console.error("Background sync error:", err);
                 // Optionally queue for later or show a toast
             });
        }

    } catch (error) {
        console.error("Save failed", error);
        alert("Error saving locally.");
    } finally {
        setIsSaving(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="flex h-full flex-col md:flex-row bg-slate-50">

      {/* LEFT: Billing Form */}
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200">
        {/* Header */}
        <div className="px-6 py-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm">
           <div>
