import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Users, Package, DollarSign, FileText, History, Menu, X, Database, CloudLightning, CheckCircle, RefreshCw, Loader2, LayoutDashboard, Printer, LogOut, User as UserIcon, ArrowUpCircle, Edit3, Download, MoreHorizontal, FileDown, Search } from 'lucide-react';
import { PartyManager } from './components/PartyManager';
import { ProductManager } from './components/ProductManager';
import { RateManager } from './components/RateManager';
import { Billing } from './components/Billing';
import { DataManager } from './components/DataManager';
import { UserManager } from './components/UserManager';
import { MoreMenu } from './components/MoreMenu';
import { InvoiceLogs } from './components/InvoiceLogs';
import { Ranking } from './components/Ranking';
import { Login } from './components/Login';
import { Store } from './services/store';
import { Cloud } from './services/cloud';
import { Party, Product, SpecialRate, Invoice, ViewState, User } from './types';
import { InvoiceTemplate } from './components/InvoiceTemplate';
import { exportInvoicesToCSV } from './services/csv';

// Declare html2pdf for TypeScript
declare global {
  interface Window {
    html2pdf: any;
  }
}

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // State
  const [validUsers, setValidUsers] = useState<User[]>(() => Store.getUsers());
  const [parties, setParties] = useState<Party[]>(() => Store.getParties());
  const [products, setProducts] = useState<Product[]>(() => Store.getProducts());
  const [specialRates, setSpecialRates] = useState<SpecialRate[]>(() => Store.getRates());
  const [invoices, setInvoices] = useState<Invoice[]>(() => Store.getInvoices());

  // UI State
  const [currentView, setCurrentView] = useState<ViewState>('billing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  // Search State for History View
  const [invoiceSearch, setInvoiceSearch] = useState('');

  // Context Menu State
  const [contextMenu, setContextMenu] = useState<{ visible: boolean; x: number; y: number; invoice: Invoice | null }>({
    visible: false,
    x: 0,
    y: 0,
    invoice: null,
  });

  // PDF Download State
  const [pdfInvoice, setPdfInvoice] = useState<Invoice | null>(null);
  const pdfContainerRef = useRef<HTMLDivElement>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Sync Status
  const [cloudUrl, setCloudUrl] = useState(() => Cloud.getScriptUrl());
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');

  const isFirstLoad = useRef(true);
  const hasPendingChanges = useRef(false);
  // This ref tracks if the current state change was caused by a Cloud Pull
  // If true, we skip the next Auto-Push to prevent overwriting the sheet with what we just downloaded
  const isRemoteUpdate = useRef(false);
  const lastPushTime = useRef(0); 

  const loadLocalData = () => {
    setParties(Store.getParties());
    setProducts(Store.getProducts());
    setSpecialRates(Store.getRates());
    setInvoices(Store.getInvoices());
    setValidUsers(Store.getUsers());
  };

  // Close context menu on click elsewhere
  useEffect(() => {
    const handleClick = () => setContextMenu({ ...contextMenu, visible: false });
    window.addEventListener('click', handleClick);
    return () => window.removeEventListener('click', handleClick);
  }, [contextMenu]);

  // Auto-Print Effect when History Preview Opens
  useEffect(() => {
    if (viewInvoice) {
      // Increased delay to 1000ms to ensure QR code image loads before print dialog
      const timer = setTimeout(() => {
        window.print();
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [viewInvoice]);

  // Handle PDF Generation
  useEffect(() => {
    if (pdfInvoice && pdfContainerRef.current && !isGeneratingPdf) {
      setIsGeneratingPdf(true);
      // Wait for render
      setTimeout(() => {
        const element = pdfContainerRef.current;
        if (!element || !window.html2pdf) {
            setIsGeneratingPdf(false);
            setPdfInvoice(null);
            return;
        }

        const opt = {
          margin: 0,
          filename: `Invoice_${pdfInvoice.invoiceNumber}.pdf`,
          image: { type: 'jpeg', quality: 0.98 },
          html2canvas: { scale: 2, useCORS: true },
          jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        window.html2pdf().set(opt).from(element).save().then(() => {
          setIsGeneratingPdf(false);
          setPdfInvoice(null);
        }).catch((err: any) => {
          console.error('PDF Generation Error:', err);
          setIsGeneratingPdf(false);
          setPdfInvoice(null);
        });
      }, 500); // Wait for QR code and layout
    }
  }, [pdfInvoice, isGeneratingPdf]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) {
      setIsAuthenticated(true);
    }
    if (cloudUrl) {
      Cloud.fetchUsers().then(cloudUsers => {
        if (cloudUsers.length > 1) { 
          setValidUsers(cloudUsers);
          Store.saveUsers(cloudUsers);
        }
      });
    }
  }, []);

  // --- AUTO-PUSH (App -> Sheet) ---
  useEffect(() => {
    Store.saveParties(parties);
    Store.saveProducts(products);
    Store.saveRates(specialRates);
    Store.saveUsers(validUsers);

    if (isFirstLoad.current) {
      isFirstLoad.current = false;
      return;
    }

    // SAFETY GUARD: Never push empty data automatically. 
    if (parties.length === 0 && products.length === 0) return;

    // REMOTE UPDATE CHECK:
    // If this change came from the Cloud (Pull), do NOT push it back.
    if (isRemoteUpdate.current) {
       isRemoteUpdate.current = false; // Reset flag
       return; 
    }

    hasPendingChanges.current = true;

    if (cloudUrl) {
      setSyncStatus('syncing');

      const handler = setTimeout(async () => {
         try {
           await Cloud.syncMasterData(parties, products, specialRates, validUsers);
           lastPushTime.current = Date.now();
           setSyncStatus('synced');
           hasPendingChanges.current = false;
           setTimeout(() => setSyncStatus('idle'), 2000);
         } catch (e) {
           console.error("Auto-sync failed", e);
           setSyncStatus('idle');
           hasPendingChanges.current = false; 
         }
      }, 2000); 

      return () => clearTimeout(handler);
    } else {
       hasPendingChanges.current = false;
    }
  }, [parties, products, specialRates, validUsers, cloudUrl]);

  // --- MANUAL FORCE PUSH ---
  const handleForcePush = async () => {
      if (!cloudUrl) return;
      setSyncStatus('syncing');
      try {
          console.log("Force Pushing Data...");
          await Cloud.syncMasterData(parties, products, specialRates, validUsers);
          lastPushTime.current = Date.now();
          setSyncStatus('synced');
          hasPendingChanges.current = false;
          setTimeout(() => setSyncStatus('idle'), 2000);
          alert("Data successfully uploaded to Google Sheet.");
      } catch(e) {
          console.error(e);
          setSyncStatus('idle');
          alert("Upload failed. Check connection.");
      }
  };

  // --- PULL LOGIC (CRITICAL DATA PROTECTION) ---
  const handleCloudPull = useCallback(async () => {
      // Don't pull if user is actively typing (pending changes) or we are already syncing
      if (syncStatus === 'syncing' || syncStatus === 'pulling' || hasPendingChanges.current) return;
      if (Date.now() - lastPushTime.current < 10000) return; 

      if (!cloudUrl) return;

      try {
        setSyncStatus('pulling');

        const [cloudPartiesRaw, cloudProductsRaw, cloudRatesRaw, cloudInvoices, cloudUsers] = await Promise.all([
           Cloud.fetchData('PARTIES'),
           Cloud.fetchData('PRODUCTS'),
           Cloud.fetchData('RATES'),
           Cloud.fetchInvoices(),
           Cloud.fetchUsers()
        ]);

        // 1. Parse Cloud Data (Parties & Products First)
        const cloudParties: Party[] = cloudPartiesRaw.slice(1).map((r: any[]) => ({
          id: String(r[0]).trim() || `PTY-${Math.random().toString(36).substr(2,9)}`, 
          name: r[1], 
          address: r[2], city: r[3], phone: r[4], 
          gstNumber: r[5], aadharNumber: r[6], panNumber: r[7], email: ''
        })).filter((p: Party) => p.name); 

        const cloudProducts: Product[] = cloudProductsRaw.slice(1).map((r: any[]) => ({
          id: String(r[0]).trim() || `PRD-${Math.random().toString(36).substr(2,9)}`, 
          name: r[1], 
          code: r[2], hsn: r[3], gstPercent: Number(r[4]), 
          qtyPerCase: Number(r[5]), standardRate: Number(r[6]), unit: r[7]
        })).filter((p: Product) => p.name); 

        // If local changes happened while fetching, abort update to protect local work
        if (hasPendingChanges.current) {
           setSyncStatus('idle');
           return;
        }

        // 2. DECIDE MASTER: CLOUD IS MASTER
        // Logic: If Cloud has valid data, we accept it. 
        // We do NOT block it if local is bigger. We assume Cloud is the Truth.

        let finalParties = parties;
        let updateParties = false;

        if (cloudParties.length > 0 && JSON.stringify(cloudParties) !== JSON.stringify(parties)) {
             finalParties = cloudParties;
             updateParties = true;
        }

        let finalProducts = products;
        let updateProducts = false;

        if (cloudProducts.length > 0 && JSON.stringify(cloudProducts) !== JSON.stringify(products)) {
             finalProducts = cloudProducts;
             updateProducts = true;
        }

        // 3. PARSE RATES based on FINAL lists
        let finalRates = specialRates;
        let updateRates = false;

        if (cloudRatesRaw.length > 0) {
            let parsedRates: SpecialRate[] = [];
            const header = cloudRatesRaw[0]; 
            const partyColMap: Record<number, string> = {};

            // Map Columns to Party IDs from FINAL PARTIES list
            for(let i=3; i<header.length; i++) {
                const pName = header[i];
                const pObj = finalParties.find(p => p.name.trim().toLowerCase() === String(pName).trim().toLowerCase());
                if(pObj) partyColMap[i] = pObj.id;
            }

            for(let i=1; i<cloudRatesRaw.length; i++) {
                const row = cloudRatesRaw[i];
                const prodId = String(row[0]).trim();
                // Match against FINAL PRODUCTS list
                const matchedProduct = finalProducts.find(p => p.id === prodId) || finalProducts.find(p => p.name === row[1]);

                if(matchedProduct) {
                    Object.entries(partyColMap).forEach(([colIdx, partyId]) => {
                        const val = parseFloat(row[Number(colIdx)]);
                        if(!isNaN(val) && val > 0) {
                            parsedRates.push({ partyId, productId: matchedProduct.id, rate: val });
                        }
                    });
                }
            }

            if (parsedRates.length > 0 && JSON.stringify(parsedRates) !== JSON.stringify(specialRates)) {
                finalRates = parsedRates;
                updateRates = true;
            }
        }

        // 4. APPLY UPDATES
        // We set the flag IS_REMOTE_UPDATE to true to block the Auto-Push effect
        if (updateParties || updateProducts || updateRates) {
           isRemoteUpdate.current = true;
           if (updateParties) setParties(finalParties);
           if (updateProducts) setProducts(finalProducts);
           if (updateRates) setSpecialRates(finalRates);
        }

        if (cloudInvoices.length !== invoices.length) {
             setInvoices(cloudInvoices);
             Store.saveInvoices(cloudInvoices);
        }

        if (cloudUsers.length > 0 && JSON.stringify(cloudUsers) !== JSON.stringify(validUsers)) {
            setValidUsers(cloudUsers);
            Store.saveUsers(cloudUsers);
        }

        setSyncStatus('idle');

      } catch (e) {
        console.error("Cloud Pull Error", e);
        setSyncStatus('idle');
      }
  }, [parties, products, specialRates, invoices, validUsers, syncStatus, cloudUrl]);

  useEffect(() => {
    if (!cloudUrl) return;
    const interval = setInterval(handleCloudPull, 10000); 
    return () => clearInterval(interval);
  }, [handleCloudPull, cloudUrl]);

  const refreshInvoices = () => {
