           </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col h-full overflow-hidden pt-14 md:pt-0 bg-slate-50/50">

        {currentView === 'billing' && (
          <Billing 
            parties={parties} 
            setParties={setParties}
            products={products} 
            specialRates={specialRates}
            onInvoiceSaved={() => {
              refreshInvoices();
              setEditingInvoice(null); // Clear editing state after save
            }}
            initialData={editingInvoice} // Pass data for editing
          />
        )}

        {currentView === 'parties' && (
          <div className="h-full overflow-y-auto">
            <PartyManager parties={parties} setParties={setParties} />
          </div>
        )}

        {currentView === 'products' && (
          <div className="h-full overflow-y-auto">
            <ProductManager products={products} setProducts={setProducts} />
          </div>
        )}

        {currentView === 'rates' && (
          <RateManager 
            parties={parties} 
            products={products} 
            specialRates={specialRates} 
            setSpecialRates={setSpecialRates} 
          />
        )}

        {currentView === 'users' && (
          <div className="h-full overflow-y-auto">
             <UserManager users={validUsers} setUsers={setValidUsers} />
          </div>
        )}

        {currentView === 'more' && (
          <div className="h-full overflow-y-auto">
             <MoreMenu invoices={invoices} parties={parties} products={products} />
          </div>
        )}

        {currentView === 'logs' && (
          <div className="h-full overflow-y-auto">
             <InvoiceLogs invoices={invoices} />
          </div>
        )}

        {currentView === 'ranking' && (
          <div className="h-full overflow-y-auto">
             <Ranking invoices={invoices} parties={parties} />
